(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-expert-choice-routing"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-1\">一 · 事故现场：一次预填把分组 GEMM 的 tile 打成锯齿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-2\">二 · 它解决什么：把负载从“统计保证”换成“机制保证”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-3\">三 · 它不解决什么：解码阶段的稀疏性退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-4\">四 · 与容量因子路由的机制差别：为什么不能靠调参绕过</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-5\">五 · 一个可落地的判断准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-6\">六 · 专家选择路由：它救的是预填期的形状抖动，不是解码期的稀疏性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-7\">七 · 专家反向选择：先划清它能救什么、救不了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-8\">八 · 打分矩阵与列方向 TopK：路由的第一步代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-9\">九 · 转置 dispatch 矩阵：从 token 主序到专家主序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-10\">十 · 固定 M=k 的分组 GEMM：tcgen05 流水线无气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-11\">十一 · combine 与残差旁路：归一化、兜底与散射回序列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-12\">十二 · 解码阶段的退化：batch 远小于 k 时稀疏性消失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-13\">十三 · 专家反转路由的边界：从固定负载到因果性与稀疏性退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-14\">十四 · 打分矩阵与列向 TopK：把选择方向翻过来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-15\">十五 · 归一化合并公式：分母为什么必须逐 token 重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-16\">十六 · 固定 c 的块布局：分组 GEMM 形状为什么不再抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-17\">十七 · 退化与兜底：decode 阶段公式还成立吗</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-18\">十八 · 代价核算：三个数字维度的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-19\">十九 · 专家选择路由的边界条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-20\">二十 · 请求形态：长预填是主战场，短解码是雷区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-21\">二十一 · 长度分布：方差决定 c 的取值下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-22\">二十二 · 并发与批大小：T 是调度器的因变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-23\">二十三 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-24\">二十四 · 配方参数：c、E 与 T 的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-25\">二十五 · 判断准则：什么负载该用 EC</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-26\">二十六 · 专家反向选择的负载配方：预填吃满、解码塌缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-27\">二十七 · 硬件档位：按 c 与专家数反推 SM 与 TMEM 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-28\">二十八 · 并行拓扑：专家维切分优先于张量维切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-29\">二十九 · 量化方案：c 固定后 tile 形状稳定，才敢上微缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-30\">三十 · KV 策略：decode 稀疏性退化决定 KV 分页粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-31\">三十一 · 调度参数：攒批阈值与 c 的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-32\">三十二 · 可复现的配置思路：从 c 出发的四步定档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-33\">三十三 · 专家反向选择路由的部署边界：从预填红利到解码退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-34\">三十四 · 固定 M=k 如何把 GEMM 的抖动成本压到零</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-35\">三十五 · All-to-All 流量被钉死为 E×k，通信从统计问题变成常数问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-36\">三十六 · 解码阶段：T 小于 k 时稀疏性塌缩，尾延迟先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-37\">三十七 · 显存与功耗：固定 tile 的驻留成本与专家权重的静态占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-38\">三十八 · 规模上去以后哪里先崩：一条按顺序失效的清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-39\">三十九 · 规模放大后先崩的是解码侧稀疏性，不是显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-40\">四十 · 精度问题：从路由掩码到数值漂移的三条链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-41\">四十一 · OOM：固定 c 带来的显存确定性与其反面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-42\">四十二 · 批抖动与路由不均：固定 tile 的两种反面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-43\">四十三 · 尾延迟尖刺：decode 阶段的退化与兜底缺失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-44\">四十四 · 监控面与回滚开关的设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-45\">四十五 · 工程判断：什么情况下不该用这套路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-46\">四十六 · 专家反向路由的失效边界与上线诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-47\">四十七 · 对照轴：谁在决定&quot;哪个 token 进哪个专家&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-48\">四十八 · 决策表：按推理阶段与负载形态落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-49\">四十九 · 公式对照：两条路径的代价函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-50\">五十 · 机制落地：固定 tile 与残差旁路的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-51\">五十一 · 适用条件与不可用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-52\">五十二 · 与容量因子路由的边界划法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-expert-choice-routing-sec-53\">五十三 · 专家选择路由的边界：与容量因子路由、分组 GEMM 调度族的取舍</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:528px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 528.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">路由器计算 token×专家 的打分矩阵 G（形状 T×E）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对每个专家列做 top-k 选择，得到该专家负责的 token 集合，每专…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">构建转置的 dispatch 矩阵（专家→token），All-to-Al…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">分组 GEMM 以固定 M=k 执行，combine 时对每个 token…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">未被任何专家选中的 token 走残差旁路，被多个专家选中的 token …</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-expert-choice-routing-sec-1\">一 · 事故现场：一次预填把分组 GEMM 的 tile 打成锯齿</h3>\n<p>某在线推理服务在 B200 上跑一个 64 专家的 MoE 模型，预填阶段用 token-choice top-2 路由配容量因子 1.25。上线首周遇到一次典型的尾延迟尖峰：一条 8k token 的长文档请求进来，路由器打分后前 8 个专家吃掉了近四成 token，其余专家大量空转。容量因子 1.25 意味着每专家最多接 <span class=\"formula-inline\">1.25 × T × k / E</span> 个 token，超出的部分被直接丢弃——这条请求里有相当一部分 token 的专家贡献被截断，输出质量下降；更糟的是分组 GEMM 的 M 维随批次内实际分配剧烈抖动，tcgen05 的固定 tile 流水线在专家负载不均时反复停顿，预填耗时被拉长到 SLO 之外。运维侧看到的不是“某个专家慢”，而是整批请求一起慢，因为分组 GEMM 是同步的：最忙的那个专家决定了整批的完成时间。</p>\n<p>这个事故暴露的不是容量因子调参问题，而是路由方向本身的结构性缺陷。token-choice 路由让每个 token 挑专家，专家负载就由数据分布决定，容量因子只能做事后截断——它把“负载不均”从计算问题转成了“丢多少 token”的质量问题。要消除丢弃，就必须让负载均衡由路由机制保证，而不是靠统计兜底。这正是专家选择路由（Expert Choice Routing）要解决的唯一问题。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-2\">二 · 它解决什么：把负载从“统计保证”换成“机制保证”</h3>\n<p>反转选择方向：不再让 token 挑专家，而是让每个专家沿 token 维挑固定数量 <span class=\"formula-inline\">c</span> 个 token。给定亲和度矩阵 <span class=\"formula-inline\">S ∈ ℝ^{T×E}</span>，专家 <span class=\"formula-inline\">e</span> 的选择集合为</p>\n<div class=\"formula\">$$\\mathcal{T}_e = \\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right)$$</div>\n<p>于是每个专家处理的 token 数严格等于 <span class=\"formula-inline\">c</span>，与数据分布无关。dispatch 矩阵转置后，All-to-All 发送量恒为 <span class=\"formula-inline\">E × c</span>，分组 GEMM 以固定 M=c 执行，tile 形状不再抖动。这是本算法唯一的核心承诺：负载均衡是路由机制的内生属性，容量因子和令牌丢弃这两个概念被整体删除。</p>\n<p>代价立刻显现。第一，因果性被破坏：一个 token 能否被专家处理，取决于同批次其他 token 的打分，自回归 decode 逐 token 生成时无法满足这个前提。第二，token 可能被 0 个专家选中（欠拟合，需要残差旁路兜底），也可能被多个专家选中（计算量翻倍），实际 FLOPs 高于 top-k 名义值。第三，combine 阶段必须按每个 token 被选中的专家数做加权平均，未被选中的 token 走残差旁路，被多个专家选中的 token 权重归一化——这套逻辑比 token-choice 的固定 top-k 归一化复杂，且在 kernel 里要多一次按 token 索引的散射与计数。</p>\n<p>具体例子：T=8192、E=64、c=128 的预填批次，token-choice top-2 下每专家平均 256 个 token 但方差极大，最忙专家可能接到 700 个；专家选择路由下每专家恰好 128 个，64 个专家共 8192 次专家调用，All-to-All 发送量精确为 8192 条。分组 GEMM 的 64 个 tile 全部同形，tcgen05 流水线无气泡。代价是这 8192 次调用覆盖的 token 去重后可能只有 6000 多个，剩余 token 走残差——这就是“实际 FLOPs 高于名义值”的来源。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-3\">三 · 它不解决什么：解码阶段的稀疏性退化</h3>\n<p>适用边界的第一条硬约束是 batch 内 token 数与 <span class=\"formula-inline\">c</span> 的关系。自回归解码时，一个 decode step 的 batch 内 token 数远小于 <span class=\"formula-inline\">c</span>，此时每个专家沿 token 维取 top-c 等价于把整个 batch 全选进来，专家选择退化为近似全选，稀疏性彻底消失。这不是调参能救的：<span class=\"formula-inline\">c</span> 是为预填的大 T 设计的，decode 的 T 只有几十到几百，机制上就无法产生有区分度的选择。</p>\n<p>由此可以给出一个工程判断：专家选择路由的规模上限由 <span class=\"formula-inline\">c</span> 与 batch 大小的比值决定。当 <span class=\"formula-inline\">T ≫ c</span> 时，选择有实际筛选意义，负载均衡收益最大；当 <span class=\"formula-inline\">T ≈ c</span> 时，选择退化为随机划分，收益归零；当 <span class=\"formula-inline\">T < c</span> 时，机制失效。因此它适合预填阶段，不适合作为 decode 的主路由。decode 侧要么回到 token-choice 配容量因子，要么用别的稀疏化手段——这部分不在本片段展开。</p>\n<p>第二条边界是兜底路由的缺失。部分 token 不被任何专家选中时，如果没有残差旁路，输出直接缺失。工程上必须显式实现“零选中 token 走残差”的分支，并在 combine kernel 里维护每个 token 的选中计数。这个计数是额外的显存读写：每个 token 一个 int8 计数器，T=8192 时不过 8KB，但散射回序列时的索引 gather 会引入一次不规则的全局内存访问，在 decode 的小 batch 下这次访问的延迟占比反而更高。</p>\n<p>第三条边界是专家数变化时的 tile 重调优。分组 GEMM 以固定 tile 执行的前提是 E 与 c 稳定；一旦专家数从 64 扩到 128，每专家 c 减半，tile 形状变化，tcgen05 流水线的 stage 划分与 TMEM 分配都要重新调优，否则流水线出现气泡。这是部署侧的隐性成本，不是算法本身的缺陷，但会吃掉“负载均衡接近 100%”带来的吞吐收益。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-4\">四 · 与容量因子路由的机制差别：为什么不能靠调参绕过</h3>\n<p>容量因子路由的负载均衡是统计保证：容量因子设得越大，丢弃越少，但分组 GEMM 的 M 维抖动越大，tile 形状越不可预测；设得越小，tile 越整齐，丢弃越多。这是一个无法同时满足的权衡，调参只是在两者之间移动工作点。专家选择路由把这个权衡从“事后截断”移到“事前选择”：负载严格等于 c，tile 严格同形，丢弃为零，代价是 token 覆盖不再有保证。</p>\n<p>用公式对比更清楚。token-choice 下专家 <span class=\"formula-inline\">e</span> 的实际负载是随机变量 <span class=\"formula-inline\">L_e = Σ_t 𝟙[e ∈ TopK(g_t)]</span>，容量因子只给出上界 <span class=\"formula-inline\">L_e ≤ CF · Tk/E</span>，超出即丢弃；专家选择下 <span class=\"formula-inline\">L_e ≡ c</span>，是确定量。前者需要运行时监控丢弃率并动态调 CF，后者不需要任何运行时反馈——但前者能保证每个 token 至少被 k 个专家处理，后者不能。这就是两条路线的本质分野：一个保 token 覆盖、牺牲负载确定性；一个保负载确定性、牺牲 token 覆盖。</p>\n<p>工程代价的量化方向：token-choice 的丢弃率每上升一个百分点，等效于损失一部分模型质量，且这部分损失不可观测；专家选择路由的 token 欠拟合率同样不可观测，但它表现为残差旁路的比例，可以在 kernel 里直接计数并暴露为指标。后者至少是可观测的，这在 SLO 运维上是实质优势。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-5\">五 · 一个可落地的判断准则</h3>\n<p>把适用边界压缩成一条可执行的判断：先看请求形态。预填为主、单请求 token 数远大于 c 的服务，专家选择路由直接消除容量因子调参和丢弃，分组 GEMM 形状固定带来的吞吐收益在 tcgen05 上尤其明显；decode 为主、batch 小的服务，机制退化，不要用。混合形态的服务，预填与解码分离部署时可以在预填侧用专家选择、解码侧用 token-choice，两侧路由不同但共享专家权重——这要求 dispatch 格式在两侧可转换，是部署层的额外工作量。</p>\n<p>再看专家数与 c 的稳定性。E 与 c 在模型生命周期内固定，tile 只需调优一次；若服务需要动态调整专家数（例如按负载弹性伸缩专家分片），固定 tile 的重调优成本会周期性出现，此时专家选择路由的收益被抵消。最后看兜底逻辑：残差旁路与选中计数必须在 kernel 里实现，不能留给框架层用 Python 拼，否则散射回序列的那次不规则访存会成为新的尾延迟来源。</p>\n<p>事故复盘落到具体机制上：那次尾延迟的根因不是容量因子设小了，而是 token-choice 让最忙专家决定了整批分组 GEMM 的完成时间。专家选择路由把“最忙专家”这个概念从系统里删掉了——每专家恰好 c 个 token，最忙与最闲没有区别，分组 GEMM 的完成时间由 c 和 tile 形状决定，不由数据分布决定。这就是它值得被单独讨论的理由：它不是又一个路由变体，而是把负载均衡从统计问题改写成机制问题的唯一一条路径。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-6\">六 · 专家选择路由：它救的是预填期的形状抖动，不是解码期的稀疏性</h3>\n<p>把这条路由当成“更好的 MoE 路由”是常见误读。它真正针对的是一个非常具体的推理病灶：token-choice 路由下，每个专家收到多少 token 由当批数据分布决定，容量因子只能在事后截断，于是分组 GEMM 的 tile 形状随批次抖动，tcgen05 流水线在 M 维上反复换挡，溢出 token 被直接丢弃。一个可复现的线上形态是：预填阶段长 prompt 涌入，少数专家被打分矩阵集中选中，容量因子兜底截断，被丢的 token 走残差旁路，输出质量在长上下文首段明显塌陷，而吞吐曲线看着正常——事故不报错，只表现为答非所问。专家选择路由把方向反过来：不再让 token 挑专家，而是每个专家沿 token 维取固定 c 个，负载由机制保证而非统计保证。选择掩码写成</p>\n<div class=\"formula\">$$\\mathcal{T}_e=\\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right),\\qquad \\sum_{t}\\mathbf{I}_{t,e}=c\\ \\ \\forall e$$</div>\n<p>于是 All-to-All 发送量严格为 E×c，分组 GEMM 以固定 M=c 执行，容量因子与令牌丢弃从代码路径里消失。代价立刻显形：token 可能被 0 个专家选中，也可能被多个专家选中。前者需要残差旁路兜底，否则该 token 的输出直接缺失；后者使实际 FLOPs 高于 top-k 名义值，combine 时必须按被选中专家数归一化，否则多专家 token 的激活被放大。这条边界决定了它只适合预填：当 T≫c 时，列 top-c 的选择有足够候选池，稀疏性成立；而自回归解码时 batch 内 token 数远小于 c，每个专家几乎把整批 token 全选走，路由退化为近似全选，稀疏性归零，收益变成纯粹的额外 All-to-All 开销。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>预填（T≫c）</th><th>解码（T≪c）</th></tr></thead><tbody><tr><td>每专家负载</td><td>严格等于 c，tile 固定</td><td>退化为近似全选</td></tr><tr><td>稀疏性</td><td>成立，FLOPs 可控</td><td>丧失，计算量接近稠密</td></tr><tr><td>主要代价</td><td>多选 token 的 FLOPs 放大</td><td>All-to-All 延迟摊薄不掉</td></tr><tr><td>失效形态</td><td>零选 token 缺输出</td><td>吞吐不升反降</td></tr></tbody></table>\n<p>系统代价要按三段拆：路由段做 T×E 打分与列 top-c，是纯带宽活；dispatch 段 All-to-All 流量确定但不可压缩，跨 NVLink 域的时延随 E×c 线性走；GEMM 段因 M 固定而流水线无气泡，这是它唯一确定性的收益。真正的工程判断在于 c 与 batch 的关系：c 调大，预填 tile 更饱满、tcgen05 利用率更高，但解码退化更早、多选 token 的 FLOPs 放大更重；c 调小，稀疏性保住，零选 token 比例上升，残差旁路承担的语义损失变大。专家数变化时固定 tile 需重新调优，否则流水线出气泡——这条不是调参琐事，而是把 c 钉死在编译期形状上的结构性约束。因此它不解决解码期稀疏性、不解决零选 token 的语义兜底、也不解决专家数弹性；它解决的是预填期“负载不可预测导致形状抖动与丢弃”这一个问题，且只在 T 远大于 c 时成立。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-7\">七 · 专家反向选择：先划清它能救什么、救不了什么</h3>\n<p>线上最典型的事故形态不是算错，而是抖动：token-choice 路由下，某几个热门专家在某一批请求里被大量 token 选中，容量因子触发截断，被截掉的 token 直接丢掉专家计算、只留残差；同一批里另一些专家却几乎空转。后果是分组 GEMM 的 tile 形状随批次漂移，tcgen05 流水线在 M 维上反复换档，端到端延迟出现无法用平均吞吐解释的尖峰，而输出质量在长尾请求上悄悄劣化。专家反向选择（expert-choice）把选择方向反过来：不再由 token 挑专家，而是每个专家沿 token 维取 top-c，</p>\n<div class=\"formula\">$$\\mathcal{T}_e=\\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right),\\qquad \\sum_{t}\\mathbf{I}_{t,e}=c\\ \\ \\forall e$$</div>\n<p>于是每个专家的负载严格等于 c，All-to-All 发送量恒为 E×c，分组 GEMM 以固定 tile 执行，容量因子与 token 丢弃从机制上消失。这正是它解决的问题：把负载均衡从“事后统计截断”变成“算法保证”，让预填阶段的 GEMM 形状确定、专家利用率接近满值。</p>\n<p>但它不解决的问题同样硬。第一是因果性：token 能否被某专家处理取决于同批其他 token 的打分，自回归 decode 必须按 batch 整体路由，与逐 token 生成不兼容；当 batch 内 token 数远小于 c 时，top-c 退化为近似全选，稀疏性消失，MoE 退化成稠密 FFN，显存带宽与功耗按稠密模型计。第二是覆盖率：反转后单个 token 可能被 0 个专家选中，若没有残差旁路或兜底路由，该 token 的输出直接缺失；也可能被多个专家选中，实际 FLOPs 高于 top-k 名义值，combine 时须按被选中数归一化。第三是形状刚性：固定 tile 在专家数或 c 变化时需重新调优，否则 tcgen05 流水线出现气泡。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>decode 阶段 batch ≪ c</td><td>近似全选、稀疏性退化</td><td>带宽与功耗按稠密计，延迟收益归零</td></tr><tr><td>无兜底路由</td><td>token 被 0 专家选中</td><td>输出缺失，需残差旁路补齐</td></tr><tr><td>专家数/c 变更</td><td>tile 形状失配</td><td>流水线气泡，吞吐下降</td></tr></tbody></table>\n<p>工程判断因此很直接：把它放在预填侧、token 数远大于 c 的批里，用固定 c 换取无丢弃与稳定 tile；decode 侧仍交给 token-choice 加容量因子，或改用小 c 配合更大的 decode batch 来维持稀疏度。规模上限由 c 与 batch 大小的关系决定，而不是由专家总数决定——这一点在容量规划时必须先算清楚。</p>\n<h3 id=\"alg-expert-choice-routing-sec-8\">八 · 打分矩阵与列方向 TopK：路由的第一步代价</h3>\n<p>专家选择路由的起点与 token 选择路由共用同一个打分算子，但读法完全相反。路由器对当前批次内全部 T 个 token 与 E 个专家计算亲和度矩阵 <span class=\"formula-inline\">G ∈ ℝ^{T×E}</span>，元素 <span class=\"formula-inline\">G_{t,e}</span> 是 token t 与专家 e 的匹配分数。这一步的输入是 token 隐状态张量（形状 T×d）与门控权重（形状 d×E），输出是完整稠密打分矩阵。代价上，它是一个 T×d×E 的 GEMM，在 T 较大时属于预填阶段的常规开销，但输出 G 必须整体驻留——这是本机制第一个显存代价：T×E 的矩阵在 T 上万、E 上百时是数十 MB 级，且必须保留到选择完成之后才能释放。</p>\n<p>关键动作在列方向：对每个专家列独立执行 top-k，即</p>\n<div class=\"formula\">$$\\mathcal{T}_e=\\text{TopK}_{\\text{col}}\\left(\\{G_{t,e}\\}_{t=1}^{T}\\right),\\qquad |\\mathcal{T}_e|=k\\ \\ \\forall e$$</div>\n<p>注意这里 k 是“每专家固定选多少 token”，与 token 侧 top-k 的语义不同：token 侧 k 是每 token 选几个专家，列方向 k 是每专家选几个 token，两者数值可以不同。列 top-k 的输入是 T×E 打分矩阵，输出是 E 个长度恰为 k 的 token 索引集合。工程上这不是一次简单的 reduce：T 可能远大于 k，需要对每列做部分排序或阈值筛选，且必须保证结果严格等于 k 个——这正是负载确定性的来源。代价体现在延迟上：列方向 top-k 是跨 token 维的规约，无法像逐 token 路由那样与 GEMM 流水重叠，它构成一个同步屏障，批次内所有 token 的打分必须全部完成才能开始选择。</p>\n<p>具体例子：预填一个 T=8192、E=64、k=128 的批次，打分矩阵为 8192×64，每列要从 8192 个候选里挑出 128 个，总选择量 64×128=8192 个 token-专家对，恰好等于 token 总数——这个等式不是巧合，而是容量设计的直接后果，它决定了后续 All-to-All 的发送量。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-9\">九 · 转置 dispatch 矩阵：从 token 主序到专家主序</h3>\n<p>选择完成后，路由必须把“token 到专家”的稀疏关系翻转成“专家到 token”的稠密块。构建的 dispatch 矩阵是选择掩码的转置：</p>\n<div class=\"formula\">$$\\mathbf{I}=\\text{TopK}_{\\text{col}}\\left(\\mathbf{G}\\right)\\in\\{0,1\\}^{T\\times E},\\qquad \\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e$$</div>\n<p>与 token 选择路由不同，这里按列求和恒等于 k，而不是按行求和恒等于 token 的 top-k。行和不再受约束：某个 token 可能一行全零（被 0 个专家选中），也可能一行有多个 1（被多个专家选中）。输入是选择索引集合，输出是按专家主序重排的 token 列表，每个专家对应一段长度严格为 k 的连续块。这一步的代价是数据搬运与索引构造：需要把 token 隐状态按专家块重新排列，形成 E 段定长缓冲，每段 k×d。显存上，这份重排缓冲的大小是 E×k×d，与批次 token 数 T×d 同量级但形状固定——固定形状正是后续分组 GEMM 能吃到满 tile 的前提。</p>\n<p>发送量由此完全确定：All-to-All 的通信量为 E×k 个 token-专家对，与数据分布无关，不随批次内容波动。这是相对容量因子路由最实质的工程收益：通信缓冲区可以按 E×k 静态分配，不需要为最坏情况留余量，也不需要运行时压缩。代价是这份确定性以因果性为代价——token 是否被某专家处理，取决于同批次其他 token 的打分排序，单个 token 无法独立决定自己的去向。</p>\n<p>具体例子：E=64、k=128 时，每个专家块是 128 个 token，若隐藏维 d=7168、以 FP8 存储，单专家块约 128×7168 字节量级，64 个块合计构成一次 All-to-All 的 payload；无论这批 token 的分布多偏斜，这个 payload 大小不变。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-10\">十 · 固定 M=k 的分组 GEMM：tcgen05 流水线无气泡</h3>\n<p>重排后的 E 个定长块直接喂给分组 GEMM。每个专家的矩阵乘 M 维恒等于 k，N 维为中间维，K 维为隐藏维。输入是 E 段 k×d 的激活与对应专家的权重，输出是 E 段 k×d' 的专家输出。这一步的代价特征与 token 选择路由形成鲜明对比：后者每个专家的 M 随批次分布抖动，tile 边界不齐，tcgen05 的 MMA 流水在尾块上出现气泡；前者 M 固定，tile 划分在编译期就能定死，流水线可以按满 tile 连续排布。</p>\n<p>代价的另一面是实际 FLOPs 高于名义值。名义计算量按每 token 被 k 个专家处理估算，但实际执行量是 E×k 个 token-专家对，而批次内只有 T 个 token。当 E×k &gt; T 时，平均每个 token 被多个专家处理，计算量翻倍；当 E×k &lt; T 时，部分 token 不被任何专家处理。系统设计必须按 E×k 而非 T×k 来估算 GEMM 时间，这是容量规划里最容易算错的一项。功耗上，固定 tile 意味着 SM 占用率稳定、无空转尾块，单位有效 FLOP 的能耗更接近峰值效率，但总算力消耗由 E×k 决定，不随稀疏性下降。</p>\n<p>具体例子：T=8192、E=64、k=128 时 E×k=8192，恰好每 token 平均被一个专家处理；若把 k 提到 256，E×k=16384，等于每个 token 平均被两个专家处理，GEMM 时间大致翻倍，而 token 数没变——这就是固定负载配方下“加容量即加算力”的直接体现。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-11\">十一 · combine 与残差旁路：归一化、兜底与散射回序列</h3>\n<p>GEMM 输出按专家块排列，必须散射回 token 主序。combine 阶段对每个 token 收集它被哪些专家选中，并按权重归一化合并：</p>\n<div class=\"formula\">$$\\mathbf{y}_t=\\frac{\\sum_e \\mathbf{I}_{t,e}\\,g_{t,e}\\,\\text{Expert}_e(\\mathbf{x}_t)}{\\sum_e \\mathbf{I}_{t,e}g_{t,e}}$$</div>\n<p>分母是该 token 被选中专家数对应的权重和，因此被多个专家选中的 token 得到加权平均而非简单相加，避免输出幅度随选中数膨胀。输入是 E 段专家输出与选择掩码，输出是 T×d' 的最终激活。代价是散射写回：需要按 token 索引做 gather/scatter，索引不规则，访存模式差，在显存带宽上是这一阶段的主要开销；若用原子累加处理多专家命中，还会引入写冲突。</p>\n<p>两个边界情况必须显式处理。其一，被 0 个专家选中的 token：分母为零，公式退化，工程上走残差旁路，直接把输入激活透传到输出，保证序列不缺失 token——这是本机制相对容量因子路由多出来的一条兜底路径，缺了它输出就会丢位置。其二，被多个专家选中的 token：归一化后合并，计算量已在前一阶段付出，combine 只做加权。失败模式很明确：若没有残差旁路，未被选中的 token 输出缺失；若归一化写错，多命中 token 的输出幅度会偏离。具体例子：一个 T=8192 的批次里若有数百个 token 行和为 0，残差旁路就是这几百个位置的唯一输出来源，其正确性直接决定序列完整性。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-12\">十二 · 解码阶段的退化：batch 远小于 k 时稀疏性消失</h3>\n<p>把上述步骤放到自回归解码，问题立刻显现。解码每步只推进一个 token 每序列，batch 内 token 总数等于并发序列数，通常远小于每专家容量 k。此时列方向 top-k 面对的是“候选数少于 k”的局面，每个专家被迫选中几乎全部候选 token，选择掩码接近全 1，稀疏性退化，E×k 的固定负载反而变成远超实际 token 数的计算量。输入是极小的 token 集，输出是近似全选的掩码，代价是 GEMM 仍按 M=k 执行，大量 tile 处理的是重复或无效的 token-专家对，算力被浪费，而延迟并不因 batch 小而下降。</p>\n<p>这解释了适用边界：本机制适合预填阶段 token 数远大于 k 的场景，那里列 top-k 有真实的选择空间，负载确定性与 tile 固定性都能兑现；解码阶段要么改用 token 选择路由，要么把解码请求攒批到 token 数超过 k 再整体路由——后者正是“按 batch 整体路由”的工程含义，它破坏了逐 token 生成的流水，却换回了稀疏性。系统判断很直接：预填用专家选择、解码用 token 选择的分阶段路由，是把两种机制的代价各自放在它能被摊薄的位置上；而固定 tile 形状在专家数或 k 变化时需要重新调优，否则 tcgen05 流水线会在新的 tile 边界上出现气泡。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-13\">十三 · 专家反转路由的边界：从固定负载到因果性与稀疏性退化</h3>\n<p>反转路由把选择方向从“token 挑专家”翻成“专家挑 token”，机制上确实把负载钉死了：对每个专家列做 top-c，得到选择掩码 $\\mathcal{T}_e=\\text{top-}c(\\{S_{t,e}\\}_{t=1}^{T})$，于是每专家负载恒等于 c，分组 GEMM 的 M 维固定、tile 形状不再抖动，All-to-All 发送量严格为 $E\\times c$。但这份确定性是用两个自由度换来的：token 被几个专家选中不再受控，且 token 能否被处理取决于同批次的其它 token。前者让实际 FLOPs 偏离 top-k 名义值，后者直接撞上自回归解码的因果约束——decode 每步只产出少量新 token，若按 batch 整体路由，一个 token 的专家归属要等整批凑齐才能确定，与逐 token 生成的流水线天然冲突。工程上这意味着该机制只能落在预填阶段或“攒批再算”的离线形态，不能嵌进对首 token 延迟敏感的在线 decode 路径。</p>\n<p>失效条件可以写成一条不等式。设批内 token 数为 $T$、每专家容量为 $c$、专家数为 $E$，则总选择槽位为 $E\\times c$，而每个 token 平均被选中次数为 $\\lambda=E c/T$。当 $T\\gg c$ 时 $\\lambda$ 小，稀疏性成立；当 $T$ 逼近或小于 $c$，$\\lambda\\ge 1$，几乎每个 token 都被至少一个专家选中，选择退化为近似全选，稀疏性消失，分组 GEMM 的实际计算量向稠密 MLP 靠拢。decode 阶段正是 $T$ 极小的 regime，因此该方案在 decode 上不仅失去省算的好处，还要付 All-to-All 的固定通信开销。反过来，$T$ 很大时又有另一头风险：被 0 个专家选中的 token 数量随 $T$ 增长，若没有残差旁路兜底，这些 token 的输出直接缺失；被多个专家选中的 token 则要按选中数归一化，计算量翻倍。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>T 与 c 的关系</th><th>稀疏性</th><th>主要代价</th></tr></thead><tbody><tr><td>预填（长 prompt、大 batch）</td><td>$T\\gg c$</td><td>成立，$\\lambda$ 小</td><td>部分 token 零选中，需残差旁路</td></tr><tr><td>预填（短序列、小 batch）</td><td>$T\\sim c$</td><td>弱化</td><td>FLOPs 高于名义 top-k</td></tr><tr><td>自回归 decode</td><td>$T\\ll c$</td><td>退化为近似全选</td><td>因果性破坏 + 固定通信开销</td></tr></tbody></table>\n<p>系统代价要按步骤拆开看。打分矩阵 $G$ 是 $T\\times E$，计算与写回本身是 $O(TE)$ 的访存；列 top-c 需要对每列做一次长度 $T$ 的归约，$E$ 列并行但每列都要扫全批 token，属于带宽受限而非算力受限的操作，在 decode 的小 $T$ 下这部分开销相对收益更显突兀。dispatch 阶段构建转置矩阵、按专家重排 token 形成 $E$ 个大小恰为 $c$ 的连续块，All-to-All 发送量确定为 $E\\times c$，好处是通信量可预算、不随数据分布漂移，坏处是它与 $T$ 解耦：$T$ 小时槽位空转，$T$ 大时槽位不够、只能靠旁路与多重选中吸收。分组 GEMM 以固定 M=c 执行，tcgen05 流水线在形状稳定时无气泡，但一旦专家数变化，固定 tile 需重新调优，否则流水线出现气泡——这是部署侧最容易被忽略的运维成本。combine 阶段按每 token 被选中数加权平均，选中数分布的长尾直接转化为归一化与散射回写的额外访存。</p>\n<div class=\"formula\">$$\\mathbf{I}=\\text{TopK}_{\\text{col}}\\left(\\mathbf{G}\\right)\\in\\{0,1\\}^{T\\times E},\\quad \\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e,\\quad \\mathbf{y}_t=\\frac{\\sum_e \\mathbf{I}_{t,e}\\,g_{t,e}\\,\\text{Expert}_e(\\mathbf{x}_t)}{\\sum_e \\mathbf{I}_{t,e}g_{t,e}}$$</div>\n<p>工程判断落在容量参数 $c$ 与批形态的匹配上：$c$ 取得过大，decode 退化与空转槽位同时恶化；$c$ 取得过小，预填阶段零选中 token 增多、旁路比例上升，等效于用残差换负载确定性。可行的折中是按阶段分派——预填走反转路由吃固定 tile 的流水线收益，decode 切回 token-choice 加容量因子，两套路由在同一服务内按请求阶段切换，代价是路由逻辑与 kernel 选择的分支复杂度，以及切换点附近 batch 重组带来的调度抖动。这条边界不是调参能绕过的，它由“专家挑 token”这一机制本身的因果结构决定。</p>\n<h3 id=\"alg-expert-choice-routing-sec-14\">十四 · 打分矩阵与列向 TopK：把选择方向翻过来</h3>\n<p>token-choice 路由的写法是沿专家维取 top-k：每个 token 从 E 个专家里挑 k 个，负载由数据分布决定，只能靠容量因子事后截断。专家选择路由把矩阵转置过来看：打分矩阵 <b>G</b> 形状为 T×E，<b>G</b><sub>t,e</sub> 是 token t 对专家 e 的亲和度（router logits 经 softmax 或 sigmoid 后的分数）。选择算子不再是行向的，而是列向的：</p>\n<div class=\"formula\">$$\\mathbf{I}=\\text{TopK}_{\\text{col}}\\left(\\mathbf{G}\\right)\\in\\{0,1\\}^{T\\times E},\\quad \\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e$$</div>\n<p>逐项读这个式子。左端 <b>I</b> 是 T×E 的 0/1 指示矩阵，行索引是 token、列索引是专家，但它的构造方式与 token-choice 完全相反：对每一列 e 单独做一次 top-k，挑出该列分数最高的 k 个 token，把这 k 个位置置 1。右端的约束 <b>∑<sub>t</sub> I<sub>t,e</sub> = k</b> 是对列求和，含义是“专家 e 恰好被 k 个 token 选中”——注意求和下标是 t，也就是沿 token 维求和，这正是列向选择的直接结果。推导的关键一步就在这里：token-choice 的约束是行和为 k（<b>∑<sub>e</sub> I<sub>t,e</sub> = k</b>），专家负载是列和的随机变量；而列向 TopK 把约束直接写在列和上，列和恒等于 k 是构造出来的恒等式，不是统计期望。负载均衡从“概率上大概齐”变成“代数上严格等”，容量因子与令牌丢弃在这个式子里根本没有位置。</p>\n<p>代价立刻显现：行和不再受控。<b>∑<sub>e</sub> I<sub>t,e</sub></b> 可以是 0、1、2……直到 E，取决于这个 token 在多少列里排进了前 k。这就是“token 可能被 0 个或多个专家选中”的代数来源，也是后面 combine 阶段必须处理归一化与残差旁路的原因。工程上，这个矩阵的构建本身很便宜：T×E 的分数做 E 次列向 top-k，等价于对 <b>G</b><sup>T</sup> 做 E 次行向 top-k，可以用一次分段归约加排序完成，输出就是转置后的 dispatch 索引（专家→token 列表），每个列表长度严格为 k。对 B200 上的实现而言，这一步的代价是 T×E 个分数的读写带宽，相对于后续分组 GEMM 的权重流量可以忽略，但它决定了后面所有 kernel 的形状确定性。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-15\">十五 · 归一化合并公式：分母为什么必须逐 token 重算</h3>\n<p>输出公式是：</p>\n<div class=\"formula\">$$\\mathbf{y}_t=\\frac{\\sum_e \\mathbf{I}_{t,e}\\,g_{t,e}\\,\\text{Expert}_e(\\mathbf{x}_t)}{\\sum_e \\mathbf{I}_{t,e}g_{t,e}}$$</div>\n<p>分子是“被选中的专家各自算一遍再按门控分数加权求和”，分母是“这个 token 被选中那些专家的门控分数之和”。逐项看：<b>I<sub>t,e</sub></b> 只做掩码，把没选中的专家项清零；<b>g<sub>t,e</sub></b> 是原始亲和度分数，不做 top-k 之外的任何截断；<b>Expert<sub>e</sub>(x<sub>t</sub>)</b> 是专家网络对同一 token 的前向。分母的存在是专家选择路由与 token-choice 的一个实质差别：token-choice 里每个 token 恰好有 k 个专家、分母是固定的 k 项之和，可以在路由阶段一次算好；这里每个 token 的选中数 n<sub>t</sub> = <b>∑<sub>e</sub> I<sub>t,e</sub></b> 是变化的，分母必须按 token 逐个重算，且当 n<sub>t</sub> = 0 时分母为 0，公式本身失效——这正是“未被任何专家选中的 token 走残差旁路”的数学原因，不是工程补丁，而是公式在该点的定义域空洞。</p>\n<p>推导的关键一步在于归一化的位置。若把归一化放在专家计算之前（先对 g 做 softmax 再乘），由于每个 token 的可见专家集合不同，softmax 的分母随 n<sub>t</sub> 变化，同一 token 在不同批次里被不同专家集合选中时会得到不同的有效权重，破坏输出的一致性；把归一化放在 combine 之后（如上式），权重只依赖该 token 实际命中的专家分数，语义上等价于“在命中集合上做加权平均”，对 n<sub>t</sub> ≥ 1 良定义。实现上这意味着 combine kernel 需要按 token 索引散射回序列时同时携带两个量：加权和与权重和，最后做一次除法。对 decode 这种每 token 只算一行的场景，这是一次额外的寄存器归约；对 prefill 的大 token 块，这是一次 T 长度的一维除法，代价可忽略，但要求 dispatch 阶段把每个 token 的 n<sub>t</sub> 记录下来，否则 combine 无法知道分母。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-16\">十六 · 固定 c 的块布局：分组 GEMM 形状为什么不再抖动</h3>\n<p>把选择写成集合形式更贴近实现：</p>\n<div class=\"formula\">$$\\mathcal{T}_e = \\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right)$$</div>\n<p>这里 c 就是每专家容量 k，<b>S<sub>t,e</sub></b> 是亲和度，<b>𝒯<sub>e</sub></b> 是专家 e 负责的 token 下标集合，|<b>𝒯<sub>e</sub></b>| = c 严格成立。机制步骤落到可实现层面是三步。第一步，算 S（T×E），对每个专家列取 top-c，得到 E×c 的选择掩码——注意输出已经按专家优先排列，天然是“专家→token”的方向。第二步，按专家维重排 token：把每个 <b>𝒯<sub>e</sub></b> 里的 token 特征从原序列位置 gather 出来，拼成 E 个长度为 c 的连续块，形成形状 (E·c)×H 的激活缓冲；被多个专家选中的 token 会在多个块里各出现一次，这是“计算量翻倍”的物理形态。第三步，分组 GEMM 以固定 tile 执行：每组 M = c 恒定，N、K 由专家权重形状决定，E 个组依次（或在 tcgen05 流水线上重叠）计算，结果按 token 索引散射回序列并做上一节的归一化合并。</p>\n<p>形状确定性的系统收益要具体说：分组 GEMM 的 tile 形状不再随批次内路由分布抖动，M 维恒为 c，调度器可以静态规划每个 CTA 的 tile 分配，tcgen05 的 MMA 流水线不需要为变长组做尾部处理，气泡被压到最低；All-to-All 的发送量严格为 E×c 个 token 的激活，通信量是常量而非期望值，这对 NVLink 5 上的专家并行尤其重要——接收端可以预分配缓冲，不需要动态流控。代价在另一侧：c 是调优参数，专家数 E 变化时固定 tile 需要重新调，否则流水线出现气泡；而 c 与 batch 内 token 数 T 的关系决定稀疏性是否还有意义。数字锚点上，材料只给出“每专家负载严格等于 c”这一恒等式与 paper-mixture-of-experts-with-expert-choic-2022 这一出处，未给出具体 T、c、E 取值，因此容量规划只能定性：c 应显著小于 T，否则列向 top-c 退化为近似全选。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-17\">十七 · 退化与兜底：decode 阶段公式还成立吗</h3>\n<p>把上面的公式放到自回归 decode 里检验，会发现两个失效点，且都能从式子里读出来。第一，稀疏性退化：decode 时一个 batch 的 token 数 T 往往远小于 c，列向 top-c 在只有 T 个候选时最多选出 T 个，实际每专家负载是 min(c, T)，当 T < c 时 <b>∑<sub>t</sub> I<sub>t,e</sub> = T</b>，每个专家把整个 batch 全收下，指示矩阵接近全 1，MoE 退化为稠密前向——名义 FLOPs 是 top-k 的稀疏值，实际 FLOPs 是 E 倍专家全算，这就是“实际 FLOPs 高于 top-k 名义值”在 decode 侧最极端的形态。第二，因果性破坏：token 能否被专家 e 处理，取决于同批次其他 token 在该列上的相对分数排名，也就是取决于 batch 组成；逐 token 生成时若每步只喂一个 token，排名没有意义，必须按 batch 整体路由，这与连续批处理中请求动态进出、batch 组成逐 step 变化的调度方式直接冲突——新请求进入会改变列内排名，已在途 token 的专家分配可能被重算，KV 与专家权重的共存布局因此需要按 batch 粒度而非请求粒度组织。</p>\n<p>兜底逻辑必须写进实现而不是留给公式。对 n<sub>t</sub> = 0 的 token，输出取残差旁路 <b>y<sub>t</sub> = x<sub>t</sub></b>（或经一个共享的稠密小投影），保证输出不缺失；对 n<sub>t</sub> > 1 的 token，按上式归一化，计算量按 n<sub>t</sub> 计。工程判断是：prefill 阶段 T 大、c 相对小，列向 top-c 的稀疏性与形状确定性收益最大，适合把专家选择路由放在预填侧；decode 阶段应改用 token-choice 或对 batch 做最小 token 数约束（把多个请求的 decode token 拼成足够大的 T 再路由），否则固定 c 的 tile 只是把稠密计算包装成稀疏形状，省不下 FLOPs 也省不下权重带宽。失败模式清单里“缺乏兜底路由时输出缺失”“专家数变化时 tile 需重调”两条，对应的正是公式定义域空洞与 c 的静态性，二者都应在 dispatch 前的校验环节显式检查，而不是在 combine 之后靠数值异常发现。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-18\">十八 · 代价核算：三个数字维度的取舍</h3>\n<p>把公式翻译成系统代价，可以按三个维度对齐。显存与带宽：dispatch 缓冲形状为 (E·c)×H，与 T 解耦，只随 c 与 E 增长；激活被重复 gather 的倍数是平均 n<sub>t</sub>，即 <b>∑<sub>t</sub> n<sub>t</sub> / T = E·c / T</b>，当 c 接近 T/E 时该比值接近 1（无重复），当 c 远大于 T/E 时激活流量按比例放大——这是选择 c 时必须算的第一个不等式。延迟：分组 GEMM 的 M 恒为 c，单组计算时间固定，总时间近似 E 次固定 tile 之和，与路由分布无关，尾延迟可预测；但 combine 的散射与逐 token 除法引入一次 T 长度的串行归约，在 decode 小 batch 下这次归约的相对占比上升。吞吐与功耗：All-to-All 流量恒为 E×c，通信时间可静态预算，NCCL 集合通信的缓冲可预分配；代价是当 T 远大于 E·c 时，大量 token 走残差旁路，专家计算利用率接近 100% 但整体模型的有效计算密度下降，功耗花在了固定 tile 的空转与旁路上。具体例子：一个 prefill 批次 T 很大、E 个专家、每专家 c 个 token，则 dispatch 发送量恰为 E·c，接收端按 E 个长度 c 的块预分配，GEMM 调度器按 c 切 tile，整条链路没有动态形状分支——这正是相对容量因子路由的确定性收益所在。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-19\">十九 · 专家选择路由的边界条件与系统代价</h3>\n<p>反转路由的收益来自一个强约束：每专家负载恒等于 c，于是分组 GEMM 的 M 维固定为 c，tile 形状不再随数据分布抖动，tcgen05 流水线可以按固定节拍排布，All-to-All 的发送量严格为 E×c。代价则全部转移到 token 一侧：token 被几个专家选中是随机变量。设 token t 被选中的专家数为 n_t，则实际计算量为 <span class=\"formula\">$$\\text{FLOPs}_{\\text{actual}}=\\sum_{t} n_t\\cdot \\text{cost}(\\text{Expert})$$</span>，而名义稀疏度只有 k。当 n_t 的分布尾部偏重时，被多个专家选中的 token 会触发重复计算，实际 FLOPs 高于 top-k 名义值；反之 n_t=0 的 token 不进入任何专家，只能走残差旁路，若缺少兜底路由，这部分 token 的输出等于未经专家变换的隐藏状态，形成欠拟合。这两个方向的失衡都无法靠容量因子修正，因为容量因子在专家选择路由里根本不存在。</p>\n<p>更硬的边界在解码阶段。自回归 decode 时，一个 batch 内的 token 数远小于 c，此时每个专家沿 token 维取 top-c 会退化为近似全选——专家数 E 乘以 c 的总容量超过了 batch 内可用 token 总数，稀疏性被稀释到接近稠密计算，路由带来的吞吐收益消失。工程判断很直接：这套机制适合预填阶段，token 数远大于 c，E×c 的固定块能被真实填满；解码阶段要么改用 token-choice 加容量因子，要么把 decode 的多个 step 攒成足够大的 batch 再整体路由，但后者与逐 token 生成的因果性冲突，需要框架层显式支持按 batch 整体路由的调度。规模上限由此被 c 与 batch 大小的关系锁死：c 越大，固定 tile 越容易填满、流水线越稳，但解码退化越早出现；c 越小，稀疏性保持得越久，固定 tile 的 GEMM 效率越差。</p>\n<p>还有一项常被忽略的代价：固定 tile 形状在专家数变化时需重新调优。E 改变意味着 All-to-All 的发送块大小、分组 GEMM 的 grid 划分、combine 阶段的散射索引全部要重排，否则 tcgen05 流水线出现气泡，固定形状带来的收益被调优开销吃掉。下表把三种失效条件与对应代价并列：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>batch token 数 ≪ c</td><td>top-c 退化为近似全选</td><td>稀疏性丢失，decode 吞吐塌陷</td></tr><tr><td>n_t=0 且无兜底</td><td>token 绕过全部专家</td><td>输出质量下降，需残差旁路补丁</td></tr><tr><td>E 变化未重调 tile</td><td>分组 GEMM 形状失配</td><td>tcgen05 流水线气泡，SM 利用率下降</td></tr></tbody></table>\n<p>伪代码落到可实现层面，关键是把“每专家恰好 c 个”写成对列的 top-c 而非对行的 top-k：对打分矩阵 S（T×E）逐列取 top-c 得到 E×c 的索引，再按专家维重排成 E 个连续块，块大小固定为 c，直接喂给分组 GEMM；combine 时按 token 被选中的专家数做加权平均，n_t=0 的 token 显式走残差。真正决定这套方案能否上线的不是公式，而是调度器能否在预填与解码之间切换路由模式，以及 c 的取值能否同时满足预填填充率与解码稀疏性两个互相拉扯的约束。</p>\n<h3 id=\"alg-expert-choice-routing-sec-20\">二十 · 请求形态：长预填是主战场，短解码是雷区</h3>\n<p>专家选择路由（Expert Choice，下称 EC）的负载配方只有一个硬约束：每个专家沿 token 维取 top-c，于是每专家负载恒等于 c，分组 GEMM 的 M 维固定。这条约束把请求形态的选择权从数据分布手里夺回来，代价是把选择权交给了调度器——你必须保证进入路由的 token 总数 T 足够大，且 c 与 T 的比例落在合理区间。预填阶段天然满足这一点：一条 8k 上下文的请求一次涌入，T 是数千量级，c 取 T/E 的某个分数即可让每个专家拿到饱满的一块。解码阶段则相反，连续批处理下每步只推进 B 个 token，B 往往只有几十到几百，若 c 接近或超过 B，top-c 沿 token 维退化为近似全选，稀疏性直接蒸发。</p>\n<p>把这件事写成判据：设专家数 E、每专家容量 c、批内 token 数 T，则名义稀疏度为</p>\n<div class=\"formula\">$$\\rho=\\frac{E\\cdot c}{T},\\qquad \\text{有效激活专家数}\\ \\approx\\ \\min\\!\\left(E,\\ \\frac{T}{c}\\right)$$</div>\n<p>当 T/c &lt; 1 时，每个专家能挑的 token 数不足 c，选择掩码被迫放宽，实际计算量向稠密 MoE 靠拢。工程上的直接后果是 decode 步的 GEMM 从稀疏分组退化为接近全专家的稠密矩阵乘，单步延迟上升而吞吐不升。具体例子：E=64、c=32 时，若解码批 B=48，则 T/c≈1.5，多数专家只能拿到不足一半容量，路由退化为“谁分数高谁上”的近似全选，分组 GEMM 的 tile 空转率极高。此时正确做法不是调 c，而是把 EC 限定在预填侧，解码侧换回 token-choice 加容量因子，或者用分块预填把解码 token 与预填 token 拼进同一批以抬高 T——这条路径与分块预填/解码 piggyback 的调度设计直接耦合，此处只指路。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-21\">二十一 · 长度分布：方差决定 c 的取值下限</h3>\n<p>EC 的 c 是全局常量，而请求长度是随机变量。若一批请求的长度分布方差大，短请求与长请求混批会让 T 的波动传导到 ρ 上：长请求主导 T，短请求贡献的 token 在 top-c 竞争中处于劣势，因为它们的亲和度打分没有更多上下文支撑。更隐蔽的问题是长度分布影响“被 0 个专家选中”的比例。EC 反转选择方向后，一个 token 能否被处理取决于它是否在某专家的 top-c 内；短请求的 token 打分区分度低，容易在所有专家列上排在 c 名之外，落入残差旁路。残差旁路保证了输出不缺失，但意味着这部分 token 完全没有经过专家变换，等效于模型容量被浪费。</p>\n<p>设 token t 被选中的专家数为 n_t，则实际 FLOPs 与名义 FLOPs 之比为</p>\n<div class=\"formula\">$$\\frac{\\text{FLOPs}_{\\text{real}}}{\\text{FLOPs}_{\\text{nom}}}=\\frac{\\sum_t n_t}{T\\cdot k},\\qquad n_t\\in\\{0,1,2,\\dots\\}$$</div>\n<p>长度分布越偏、批内语义越杂，n_t 的分布越散：少数 token 被多个专家重复计算（n_t&gt;1），多数 token 被 0 或 1 个专家选中。前者抬高实际算力开销，后者降低有效容量。工程判断是：c 的取值应使得在目标长度分布的下四分位上，T/c 仍显著大于 1；若线上 P25 长度对应的 T 只有 c 的两三倍，就该把该流量切到 token-choice 路径。代价体现在显存与带宽上：固定 tile 的激活缓冲按 E×c 预分配，c 调大直接吃掉显存，而分页 KV 与专家权重共存显存的那部分预算并不会因此让路。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-22\">二十二 · 并发与批大小：T 是调度器的因变量</h3>\n<p>EC 把批大小从“性能旋钮”变成了“正确性前提”。在 token-choice 下，批越大越好，因为摊薄权重读取；在 EC 下，批大小必须先满足 T ≥ E·c 的量级，否则路由本身失效。连续批处理系统里，T 不是配置项而是运行时的因变量：它等于当前在途请求的预填 token 加上解码 token。并发上升时 T 上升，ρ 下降，稀疏性变好；并发塌陷时 T 骤降，ρ 飙升，GEMM 形状向稠密靠拢。这意味着 EC 部署的容量规划必须按“最小并发”而非“峰值并发”来定 c，与常规按峰值定容量的直觉相反。</p>\n<p>伪代码层面的调度判据可以写成：</p>\n<ul>\n<li>每步统计待路由 token 总数 T；若 T &lt; α·E·c（α 为安全系数），本步回退到 token-choice 路由并启用容量因子；</li>\n<li>否则执行列 top-c，构建 E×c 的转置 dispatch 矩阵，All-to-All 发送量严格为 E×c；</li>\n<li>分组 GEMM 以固定 M=c 执行，combine 阶段按 n_t 归一化，n_t=0 的 token 走残差。</li>\n</ul>\n<p>这条判据的代价是双路由路径共存：两套 dispatch 缓冲、两套 GEMM 形状，编译期要保留两份 kernel 变体，切换点若抖动会造成流水线气泡。具体例子：一个在线服务在夜间低峰并发跌到个位数请求，T 只有几百，若 c 按日间峰值调好的值不变，则每步都触发回退，EC 的收益归零而双路径开销照付。正确做法是把 c 与并发档位绑定，低峰期缩小 c 并接受更细的 tile，或者干脆把低峰流量导向分离式部署中的解码集群。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-23\">二十三 · 负载不对时的三种塌陷</h3>\n<p>第一是稀疏性塌陷，即上文 T/c&lt;1 导致的近似全选，表现为 decode 单步延迟不降反升。第二是覆盖塌陷：部分 token 不被任何专家选中，若实现里没有残差旁路兜底，输出直接缺失；即便有旁路，被旁路的 token 比例随长度分布方差上升而上升，等效模型变浅。第三是形状塌陷：固定 tile 形状在专家数 E 变化时（例如弹性伸缩把 E 从 64 调到 48）需要重新调优 c 与 tile 切分，否则 tcgen05 流水线的 stage 数与 tile 尺寸不匹配，出现流水气泡。三种塌陷的共同点是它们都不体现在路由正确性上，只体现在延迟与吞吐的偏离上，监控必须直接采集 n_t 的直方图与每步 T 的分布，而不是看平均利用率。</p>\n<table class=\"mini\"><thead><tr><th>塌陷类型</th><th>触发条件</th><th>系统代价</th><th>观测信号</th></tr></thead><tbody><tr><td>稀疏性塌陷</td><td>T/c &lt; 1，解码批小</td><td>单步延迟上升，吞吐不增</td><td>每步 T 分布、有效激活专家数</td></tr><tr><td>覆盖塌陷</td><td>长度分布方差大、打分区分度低</td><td>有效模型容量下降，残差旁路比例上升</td><td>n_t=0 的 token 占比</td></tr><tr><td>形状塌陷</td><td>E 弹性变化后 c/tile 未重调</td><td>tcgen05 流水气泡，GEMM 利用率下降</td><td>分组 GEMM 实际 M 与 c 的偏差</td></tr></tbody></table>\n<p>具体例子：某服务把 E 从 64 缩到 32 以省显存，c 未同步减半，于是每专家容量翻倍、T/c 减半，预填侧也跌进稀疏性塌陷区，表现为预填吞吐下降而 GPU 利用率显示满载——因为 tile 里塞的是重复计算的 token。这类问题的根因不在 kernel 而在负载配方与并发的耦合。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-24\">二十四 · 配方参数：c、E 与 T 的三角约束</h3>\n<p>把负载配方写成一条可执行的工程不等式，比任何调参经验都可靠。给定目标稀疏度 ρ_target 与目标批内 token 下界 T_min，容量必须满足</p>\n<div class=\"formula\">$$c\\ \\le\\ \\frac{\\rho_{\\text{target}}\\cdot T_{\\min}}{E},\\qquad E\\cdot c\\ \\le\\ T_{\\min}$$</div>\n<p>两条约束同时成立才保证最坏情况下仍有稀疏性。反过来，c 也不能太小：c 小于 tcgen05 分组 GEMM 的最小 tile M 时，固定形状的优势被 tile 填充浪费抵消，每专家实际执行的是被 padding 撑大的 tile。因此 c 的可行区间是 [M_tile, ρ·T_min/E]，区间宽度由 T_min 决定。T_min 越小，区间越窄，EC 的适用性越差——这就是为什么 EC 适合预填而不适合纯解码。</p>\n<p>工程上的落地方式是分层配方：预填路径取较大的 c 与较大的 T_min（按最大预填块长度定），解码路径不启用 EC；混合批场景下用分块预填把解码 token 并入预填批以抬高 T，但要注意这会让解码 token 的因果性依赖于同批预填 token 的路由结果，与逐 token 生成的语义有偏差。带宽侧的代价是 All-to-All 发送量恒为 E×c，与 T 无关：T 大时通信占比低，T 小时通信成为固定开销，NVLink 5 上的 All-to-All 在小 T 下反而成为瓶颈。功耗侧，固定 tile 让 SM 占用率平稳，避免了 token-choice 下 tile 抖动带来的时钟波动，这是 EC 在稳定 SLO 上的隐性收益。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-25\">二十五 · 判断准则：什么负载该用 EC</h3>\n<p>把适用性收敛成三条可测的判据。其一，预填 token 数下四分位对应的 T 至少是 E·c 的数倍，保证最坏批也不塌陷。其二，长度分布的对数标准差可控，短请求不会被系统性旁路；若不可控，需在路由前做长度分桶，把同量级长度的请求拼批，这本身是批调度的事，EC 只消费其结果。其三，专家数 E 在部署周期内稳定，或弹性伸缩时 c 随之联动，避免形状塌陷。三条同时满足时，EC 的收益是确定的：All-to-All 流量与 GEMM 形状完全可预测，tcgen05 流水线无气泡，容量因子与令牌丢弃整套机制可以删除。</p>\n<p>反过来，纯解码服务、超短请求为主的对话前端、并发波动剧烈且无法分桶的流量，都不该把 EC 放在主路径上。一个务实的折中是：预填侧用 EC 拿确定性，解码侧保留 token-choice 加容量因子，两侧共享同一套专家权重但走不同的 dispatch 路径，切换点放在预填与解码的边界上而非每步判定——这样双路径开销只落在边界，不会在稳态里反复抖动。负载配方从来不是路由算法自己的属性，它是路由算法与调度器之间的一份契约，c 就是这份契约里的违约金条款。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-26\">二十六 · 专家反向选择的负载配方：预填吃满、解码塌缩</h3>\n<p>这套反向路由的负载配方只有一句话：让每专家处理令牌数严格等于容量 <code>c</code>，于是分组 GEMM 的 tile 形状在编译期就固定下来。它的甜点区是<b>预填阶段</b>——当批内令牌数 <code>T</code> 远大于 <code>c</code> 时，每个专家列做 top-c 选择才有真正的竞争，稀疏性成立，All-to-All 发送量恰好为 <code>E×c</code>，tcgen05 流水线可以按固定 M 排布而无气泡。反过来，当 <code>T</code> 接近甚至小于 <code>c</code> 时，top-c 退化为“几乎全选”，每专家负载仍等于 <code>c</code>，但 <code>c</code> 已经装下了整个批次，稀疏性归零，算力全花在重复计算上。</p>\n<p>失效条件可以用一个比值刻画。设批内令牌数为 <code>T</code>、专家数为 <code>E</code>、每专家容量为 <code>c</code>，则名义稀疏度与实际计算量的偏离由下式给出：</p>\n<div class=\"formula\">$$\\rho=\\frac{E\\cdot c}{T},\\qquad \\text{有效激活专家数}\\ \\approx \\min\\!\\left(E,\\frac{T}{c}\\right)$$</div>\n<p>当 <code>ρ≥1</code>（即 <code>T≤E·c</code>）时，每个令牌平均被选中的专家数不少于 1，token 被 0 个专家选中的概率下降，但被多个专家选中的概率上升，实际 FLOPs 高于 top-k 名义值；当 <code>T≪c</code> 时，<code>ρ</code> 爆掉，选择掩码近乎全 1，分组 GEMM 的固定 tile 里塞满重复令牌，吞吐被无谓放大而延迟不降。自回归解码正是后一种形态：逐 token 生成时 batch 内令牌数远小于 <code>c</code>，路由必须按整个 batch 整体做，因果性被破坏，且稀疏性退化——这是该方案在解码侧的结构性短板，不是调参能修的。</p>\n<p>负载不对时的系统代价分三处显形。其一，<b>显存与带宽</b>：All-to-All 发送量恒为 <code>E×c</code>，与真实令牌数脱钩，解码小 batch 下这部分通信成为纯开销，NVLink 5 上的链路被固定流量占满而有效载荷极低。其二，<b>延迟</b>：固定 tile 形状在专家数 <code>E</code> 变化时必须重新调优，否则 tcgen05 流水线出现气泡，预填的长序列反而被 tile 边界切碎。其三，<b>正确性兜底</b>：部分令牌不被任何专家选中时走残差旁路，若部署侧没有显式兜底路由，输出直接缺失；被多个专家选中的令牌需按权重归一化合并，归一化分母为选中专家亲和度之和，漏算即引入数值偏差。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>T 与 c 关系</th><th>稀疏性</th><th>主要代价</th></tr></thead><tbody><tr><td>长预填、大 batch</td><td>T ≫ E·c</td><td>成立</td><td>All-to-All 固定流量可控</td></tr><tr><td>中等 batch 混合负载</td><td>T ≈ E·c</td><td>部分退化</td><td>重复计算抬升 FLOPs</td></tr><tr><td>自回归解码</td><td>T ≪ c</td><td>近似全选</td><td>通信纯开销、因果性破坏</td></tr></tbody></table>\n<p>工程判断因此很直接：把反向路由钉在预填侧，用连续批处理把预填批尽量做厚以维持 <code>T≫E·c</code>；解码侧要么切回 token-choice 加容量因子，要么在分离式预填/解码架构里让解码 worker 走另一套路由。容量 <code>c</code> 的取值应按目标预填批的令牌数下界反推，而不是按专家数均分——<code>c</code> 定得过大，解码退化更早；定得过小，预填侧 tile 太窄、tcgen05 流水线填不满。</p>\n<h3 id=\"alg-expert-choice-routing-sec-27\">二十七 · 硬件档位：按 c 与专家数反推 SM 与 TMEM 预算</h3>\n<p>专家选择路由把分组 GEMM 的 M 维钉死在 c 上，这一条直接决定了硬件选型的推理顺序：先定 c，再看 E×c 的 All-to-All 发送量，最后才落到 SM 数量与 TMEM 容量。Blackwell 上 tcgen05 的 MMA 以 2-SM 配对执行，一个 CTA pair 承担一块固定 tile，tile 的 N 维取专家隐层宽度，M 维取 c 的分块。若 c 不是 2-SM MMA 的 M 粒度整数倍，配对内的两个 SM 会有一半周期空转，这是最容易被忽略的档位失配。工程判断：把 c 取成 128 的整数倍（对应 BF16/FP8 下 tcgen05 的推荐 M 粒度），使每专家恰好落在整数个 CTA pair 上，避免尾部 tile 拉长流水线。</p>\n<p>显存侧要同时装下三样东西：专家权重、转置 dispatch 缓冲、KV cache。前两者在别的片段已展开，这里只给约束式。设单专家权重字节数为 W_b，则权重驻留下限为</p>\n<div class=\"formula\">$$M_{\\text{exp}} \\ge E \\cdot W_b \\cdot \\left(1 + \\text{replica}\\right)$$</div>\n<p>其中 replica 为专家并行组内的副本数。B200 单卡 HBM 容量足以在 FP8 下容纳中等规模 MoE 的全量专家，但一旦上 NVFP4 微缩放并把 c 拉大，dispatch 缓冲的峰值会与权重争抢同一块 HBM，此时应把 dispatch 缓冲放到对端卡的接收区而非本地暂存。代价体现为带宽：E×c 个 token 隐藏状态经 NVLink 5 单向搬运，发送量与 c 线性相关，c 翻倍即 All-to-All 字节翻倍，decode 阶段的尾延迟随之抬升。</p>\n<p>具体例子：E=64、c=256、隐藏维 7168、FP8 存储，单次 dispatch 的发送量约为 64×256×7168 字节量级，落在单卡 NVLink 5 带宽的毫秒级搬运窗口内；若把 c 提到 512 而不加专家并行度，同一窗口内的搬运时间近似翻倍，直接吃掉分组 GEMM 省下的气泡收益。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-28\">二十八 · 并行拓扑：专家维切分优先于张量维切分</h3>\n<p>专家选择路由的通信形态是「全发送、按专家散射」，与张量并行的 all-reduce 形态正交。拓扑选择的第一原则是让 E×c 的发送量落在 NVLink 域内，跨节点只承载激活值而非专家权重。GB200 NVL72 的机柜级 NVLink 域使 E 可以跨 72 个 GPU 切分而无需 InfiniBand 参与 dispatch，这是该路由在 NVL72 上最自然的落点。第二原则是副本数与 c 的乘积不超过单卡 GEMM 的吞吐拐点：副本用于吸收热点专家，但本路由已保证每专家负载恒为 c，副本的唯一意义是缩短单专家 GEMM 的串行时长，而非均衡负载。</p>\n<p>伪代码思路如下，描述拓扑装配的判定顺序：</p>\n<ul>\n<li>读入 E、c、隐藏维、目标 SLO 的 decode 尾延迟；</li>\n<li>若 E×c×hidden 的发送字节在单 NVLink 域带宽下可于 SLO 预算内完成，则取专家并行度 = E，副本 = 1；</li>\n<li>否则按 E 切分到多个 NVLink 域，域间只做结果散射，dispatch 走 NIXL 的点对点传输；</li>\n<li>若单专家 GEMM 时长成为瓶颈，增加副本并把 c 按副本数均分，保持总发送量不变。</li>\n</ul>\n<p>代价落在两个方向：专家并行度越高，单卡持有的专家越少，权重驻留压力下降但 dispatch 跳数上升；副本越多，权重显存翻倍而 GEMM 串行时长缩短。工程上以「dispatch 字节 × 跳数」与「单专家 GEMM 时长 × 串行层数」两项做取舍，前者主导预填，后者主导解码。</p>\n<p>具体例子：预填阶段 T 远大于 c，E×c 发送量相对 T×hidden 的输入规模占比小，拓扑应优先拉高专家并行度以摊薄权重；解码阶段 batch 内 token 数可能小于 c，此时稀疏性退化（见失败模式），拓扑应收缩专家并行度、提高副本，用稠密小 GEMM 换低尾延迟。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-29\">二十九 · 量化方案：c 固定后 tile 形状稳定，才敢上微缩放</h3>\n<p>量化方案的选择受制于一个前提：分组 GEMM 的 tile 形状必须稳定，否则微缩放的块尺度会随 tile 边界漂移。专家选择路由恰好提供了这个稳定性——每专家恰好 c 个 token，tile 的 M 维不随请求形态抖动，因此 NVFP4 的 16 元素微缩放块可以严格对齐到 tile 内部，不跨 tile 边界取尺度。这是本路由相对容量因子路由在量化上的实质优势：后者因 tile 形状抖动，微缩放块被迫在边界处做保守缩放，等效精度损失更大。</p>\n<p>量化粒度的取舍：权重用 NVFP4 微缩放，激活用 FP8 动态缩放，是 Blackwell 上分组 GEMM 的常见组合。代价是反量化开销落在 GEMM 的加载阶段，若 c 过小导致每 tile 的 K 维循环次数不足以摊薄反量化，吞吐会被反量化指令吃掉。判据可写成</p>\n<div class=\"formula\">$$\\text{efficiency} \\approx \\frac{c \\cdot N \\cdot K}{c \\cdot N \\cdot K + \\alpha \\cdot c \\cdot N \\cdot K_{\\text{deq}}}$$</div>\n<p>其中 α 为反量化相对 MMA 的单元素代价系数，K_deq 为需反量化的通道数。c 越大，分母中的固定开销占比越小。工程判断：c 低于某个阈值时退回 FP8 权重，避免反量化成为主瓶颈；该阈值由实测的 α 决定，材料未给出具体数值，需在目标卡上以固定 tile 扫描确定。</p>\n<p>具体例子：同一 E 与隐藏维下，c=128 时每 tile 的 K 循环较短，NVFP4 反量化的固定开销占比高，实测吞吐可能低于 FP8；c=512 时 K 循环拉长，NVFP4 的带宽收益开始兑现。这说明量化方案不能脱离 c 单独选，二者必须联合调优。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-30\">三十 · KV 策略：decode 稀疏性退化决定 KV 分页粒度</h3>\n<p>本路由在解码阶段的根本矛盾是 batch 内 token 数可能远小于 c，专家选择退化为近似全选，稀疏性消失。此时 KV cache 的压力形态随之改变：不再是「少量专家被激活、KV 按专家分片」，而是「全部专家参与、KV 访问弥散」。分页 KV 的块大小应据此调大，减少页表项数量以降低弥散访问的 TLB 压力；同时把 KV 的驻留与专家权重的驻留解耦，避免 decode 阶段全专家激活时权重与 KV 争抢同一块 HBM。</p>\n<p>策略上给出两条分支：预填阶段 T 远大于 c，KV 写入量大但访问集中，采用细粒度分页以支持跨请求的块复用；解码阶段 batch 小于 c，采用粗粒度分页并把 KV 尽量驻留在 L2 可覆盖的窗口内，用带宽换命中率。代价是粗粒度分页在请求长度差异大时产生内部碎片，显存利用率下降，需以请求长度分布做容量规划。</p>\n<p>具体例子：一个 batch 内仅有数十个 decode token 而 c 为数百时，每专家实际只处理个位数 token，分组 GEMM 的 M 维远小于 tile，tcgen05 流水线出现气泡（见失败模式）。此时应把多个 decode step 的 token 攒批到接近 c 再路由，用调度参数换 GEMM 效率，代价是首 token 延迟上升。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-31\">三十一 · 调度参数：攒批阈值与 c 的联动</h3>\n<p>调度参数的核心是一个联动量：攒批阈值 B_thresh 与每专家容量 c。解码阶段若逐 step 路由，batch 内 token 数 T_b 小于 c 即退化；若攒批到 T_b ≥ c 再路由，稀疏性恢复但首 token 延迟增加。可写成约束</p>\n<div class=\"formula\">$$T_b \\ge c \\quad \\Rightarrow \\quad \\text{sparsity preserved},\\qquad \\text{TTFT} \\propto \\frac{c}{\\text{arrival rate}}$$</div>\n<p>工程判断：把 c 设为可调参数而非编译期常量，使调度器能按当前到达率在「攒批到 c」与「降 c 保稀疏」之间切换。c 降低时 tile 变小、GEMM 效率下降，但 TTFT 缩短；c 升高时反之。这条曲线的最优点由 SLO 的 TTFT 与 TPOT 两个约束共同切出，材料未给出具体 SLO 数值，需按业务侧约束实测标定。</p>\n<p>另一个调度参数是兜底路由的触发条件。部分 token 不被任何专家选中时需走残差旁路，旁路比例随 c 与 T 的比值变化：c 相对 T 越大，每专家挑选的 token 越可能覆盖全体，未被选中的 token 越少。调度器应监控旁路比例，比例异常升高说明 c 与 T 失配，需下调 c 或提高攒批阈值。代价是旁路 token 不参与专家计算，其表示质量下降，属于用精度换吞吐的显式开关。</p>\n<p>具体例子：到达率低时若坚持攒批到 c=512，TTFT 被拉长到不可接受；此时把 c 降到 128 并接受 GEMM 效率损失，TPOT 反而因 batch 内稀疏性恢复而改善。这说明调度参数不是静态配置，而是随负载形态滑动的运行期量。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-32\">三十二 · 可复现的配置思路：从 c 出发的四步定档</h3>\n<p>把上述五节收束成一条可复现的定档路径，顺序不可颠倒，因为每一步的输出是下一步的输入。</p>\n<ul>\n<li>第一步定 c：按目标 SLO 的 TPOT 与到达率，取 c 为 2-SM MMA 的 M 粒度整数倍，并保留运行期可调；</li>\n<li>第二步定量化：以固定 tile 扫描 NVFP4 与 FP8 的吞吐拐点，c 低于拐点则退回 FP8，高于拐点则上 NVFP4 微缩放；</li>\n<li>第三步定拓扑：以 E×c×hidden 的发送字节对单 NVLink 域带宽做预算，决定专家并行度与副本数，跨域只走结果散射；</li>\n<li>第四步定 KV 与调度：预填用细粒度分页、解码用粗粒度分页，攒批阈值与 c 联动，兜底旁路比例纳入监控。</li>\n</ul>\n<p>这条路径的代价是调优周期长：c、量化、拓扑、调度四者互相耦合，任一项变动都要重扫。工程上以固定 tile 的扫描脚本把四步串成一次自动搜索，把「c 与量化的吞吐拐点」作为第一维、「拓扑的 dispatch 字节预算」作为第二维，避免人工逐项试错。失败模式的判据也在此固化：若 decode 阶段旁路比例升高且 GEMM 气泡增多，说明 c 与 T_b 失配，应触发 c 下调而非加副本。</p>\n<p>具体机制落点：tcgen05 流水线无气泡的前提是每专家恰好一块固定 tile，这一前提由 c 的取值保证，而非由调度事后修补。因此配置思路的第一性原理是「c 是硬件契约，不是调度旋钮」——调度只能在 c 的整数倍附近滑动攒批阈值，不能改变 tile 形状本身。把这条契约写进部署配置的校验环节，才能在专家数变化时避免重新调优导致的流水线气泡。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-33\">三十三 · 专家反向选择路由的部署边界：从预填红利到解码退化</h3>\n<p>把反向路由落进生产配置，第一道约束来自 token 数与容量 c 的比例关系。设批内 token 数为 T、专家数为 E、每专家容量为 c，则总派发量恒为 E·c，而名义稀疏度是 T·k。当 T≫c 时，每个专家列上的 top-c 只是从大量候选中截取，选择具有实际区分度，分组 GEMM 的 M 维固定为 c，tcgen05 流水线可以按固定 tile 排布而无气泡；一旦 T 接近或小于 c，top-c 退化为对全部 token 的近似全选，未被选中的 token 反而成为少数，稀疏性名义上仍在、实际 FLOPs 却逼近稠密。工程判断因此很直接：这套配方应绑定在预填或大 batch 聚合场景，解码侧不应沿用同一 c，而应按 batch 实际 token 数动态收缩容量，否则省下的显存会被翻倍的计算吃掉。</p>\n<p>第二个边界是 token 覆盖的不对称。列方向 top-c 保证 <span class=\"formula\">$$\\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e$$</span>，却对行方向不作任何承诺：某个 token 可能被 0 个专家选中，走残差旁路；也可能被多个专家选中，combine 时按被选中数归一化，其实际计算量随命中数线性上升。于是真实 FLOPs 为 <span class=\"formula\">$$\\text{FLOPs}_{\\text{real}}=\\sum_{t}\\left(\\sum_e \\mathbf{I}_{t,e}\\right)\\cdot \\text{cost}(\\text{Expert})$$</span>，高于 top-k 名义值，且方差由数据分布决定、无法从事前容量因子推出。部署时必须为多命中 token 预留 combine 带宽与归一化开销，并为零命中 token 配置兜底路由（如固定旁路到共享专家或稠密 FFN），否则输出会出现缺失而非降级。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>容量 c 与 batch 关系</th><th>主要系统代价</th><th>失效表现</th></tr></thead><tbody><tr><td>预填</td><td>T≫c</td><td>All-to-All 流量固定为 E·c，GEMM tile 稳定</td><td>专家数变更后 tile 需重调，否则流水线气泡</td></tr><tr><td>解码</td><td>T≲c</td><td>稀疏性退化，计算量趋近稠密，延迟上升</td><td>近似全选，省显存不省算力</td></tr><tr><td>混合批</td><td>预填与解码同批</td><td>需按 batch 整体路由，破坏逐 token 因果生成</td><td>token 处理依赖同批其他 token</td></tr></tbody></table>\n<p>第三层代价在并行拓扑与调度参数上。由于 All-to-All 发送量严格等于 E·c，通信量不再随实际负载波动，这既让 NVLink 5 上的带宽预算可静态核算，也让 EP 组的 rank 数必须与 E 和 c 的乘积匹配：EP 组过大时单 rank 分到的固定块变小，分组 GEMM 的 tile 利用率下降；EP 组过小时单 rank 需承接多个专家的固定块，TMEM 与权重驻留压力上升。调度侧应把 c 作为一等参数暴露给连续批处理控制器，按请求的预填长度与解码步数分别设定，而不是全局一个常数。量化方案上，固定 tile 形状使 NVFP4/FP8 的缩放因子布局可以预先编译，但专家数变化会触发重调优，这是该配方最容易被忽视的运维成本。</p>\n<h3 id=\"alg-expert-choice-routing-sec-34\">三十四 · 固定 M=k 如何把 GEMM 的抖动成本压到零</h3>\n<p>专家选择路由真正卖给的，不是算法优雅，而是分组 GEMM 的 <em>形状确定性</em>。在 token-choice 下，每个专家收到的 token 数由当批数据分布决定，容量因子只是事后截断的上限；于是分组 GEMM 的 M 维在专家之间长短不一，tcgen05 的 tile 调度必须按最长专家对齐，短专家尾部留下空洞。空洞不是免费的：一个 128 行的 tile 里只装了 40 个有效 token，Tensor Core 仍然要跑完整个 tile 的 MMA 周期，SM 的发射槽被无效行占住，吞吐按有效 FLOPs 折算直接掉到名义值的零头。专家选择把方向反过来——每个专家沿 token 维取 top-c，于是 <span class=\"formula\">$$\\mathcal{T}_e=\\text{top-}c\\left(\\{S_{t,e}\\}_{t=1}^{T}\\right)$$</span> 保证每个专家恰好拿到 c 个 token，M=k 成为编译期常量。分组 GEMM 的 tile 数、每 tile 的行数、TMEM 的分配全部静态可算，tcgen05 流水线在专家之间切换时不需要重新对齐，气泡被结构性消除。</p>\n<p>代价转移到别处：M 固定意味着 <em>计算量固定</em>。名义 FLOPs 是 E×k×每 token 专家前向，但一个 token 可能被 0 个专家选中，也可能被 3 个专家同时选中。被多选的 token 在 combine 阶段按被选中数归一化，其前向被重复计算了多次；被零选的 token 走残差旁路，不消耗专家算力但也不获得任何专家容量。因此实际 FLOPs 高于名义值，且这个超出量由打分矩阵的列 top-k 重叠度决定，而不是由容量因子决定。工程上要盯的是 <em>重叠率</em>：若平均每 token 被选中的专家数显著大于 1，固定 M=k 带来的形状收益会被重复计算吃掉。这是本方案第一个会崩的地方——不是显存，不是通信，是有效算力利用率随重叠率线性下滑。</p>\n<p>具体例子：预填阶段一批 8192 个 token、64 个专家、每专家 k=128。总选择槽位 64×128=8192，恰好等于 token 数，平均每 token 一个槽位。若打分矩阵的列 top-k 高度重叠，比如 20% 的 token 被两个专家同时选中，那么就有等量 token 无人认领，实际专家前向次数仍是 8192 次但覆盖的 token 只有约 6554 个，剩余 token 只拿残差。分组 GEMM 的 tile 形状依旧完美，可模型质量与算力都出现了隐性漏损。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-35\">三十五 · All-to-All 流量被钉死为 E×k，通信从统计问题变成常数问题</h3>\n<p>专家并行下 dispatch 的发送量在 token-choice 里是随机变量：每专家收多少 token 取决于路由分布，All-to-All 的缓冲要按容量因子上限预留，实际发送量在均值附近波动。专家选择把发送量变成常数——dispatch 矩阵是转置的专家到 token 映射，每个专家恰好 k 个 token，总发送量严格为 E×k 个 token 的隐状态。这让 NVLink 5 上的通信规划从“按峰值预留”变成“按常数排布”：每个 rank 的发送缓冲大小、NCCL 的 chunk 切分、NIXL 的传输描述符数量都可以在编译期定死，不需要运行时自适应。对 NVL72 这种单域内全互联的拓扑，常数流量意味着集合通信的算法选择（ring 还是 tree、chunk 大小）可以针对固定消息量做静态最优，而不是在波动中反复重配置。</p>\n<p>但常数流量有一个隐藏的带宽代价：<em>负载在 rank 间不均</em>。每专家负载严格等于 k，可专家到 rank 的映射是静态的，于是某些 rank 上的专家被高频选中、另一些被冷落——不，专家选择恰恰消除了这一点，因为每个专家都恰好 k 个 token，rank 间的不均只来自每 rank 承载的专家数不同。真正的问题是 token 的 <em>来源</em> 不均：某个 rank 上的 token 可能大量流向远端专家，而本地专家的入向流量很少，形成单向偏斜。All-to-All 的带宽是双向对称的，单向偏斜会让一半链路空转。工程判断：按专家数而非按历史流量做 rank 映射，并在 dispatch 前做一次轻量的 token 重排，把来源分散到各 rank，代价是一次本地显存搬运，收益是 All-to-All 的链路利用率。</p>\n<p>公式层面，发送量 <span class=\"formula\">$$\\text{Vol}_{\\text{A2A}}=E\\times k\\times d_{\\text{hidden}}\\times \\text{bytes}$$</span> 与批内 token 数 T 无关，只与专家数、k、隐层宽度和精度有关。这意味着增大 batch 不会增加单次 dispatch 的通信量，但会稀释通信在总时延中的占比——这是专家选择在预填阶段吞吐好看的结构性原因。反过来，decode 阶段 T 很小，E×k 的发送量可能超过 T 本身，通信变成纯开销。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-36\">三十六 · 解码阶段：T 小于 k 时稀疏性塌缩，尾延迟先崩</h3>\n<p>这是本方案最硬的失败模式。自回归解码时，一个 batch 内的 token 数 T 远小于每专家容量 k。列 top-k 选择在 T&lt;k 时退化为“全选”——每个专家只能从这 T 个 token 里挑，挑不满 k 就把全部 T 个都收下。于是每个 token 被几乎所有专家选中，稀疏性消失，MoE 退化成稠密前向，计算量按 E 倍膨胀。更糟的是因果性被破坏：token 能否被某专家处理取决于同批其他 token 的打分，单 token 生成无法独立路由，必须整批路由，与连续批处理里请求随时进出、batch 组成动态变化的调度模型直接冲突。</p>\n<p>尾延迟在这里先崩，而不是吞吐。decode 的 SLO 是 TPOT，固定 M=k 的分组 GEMM 在 T 小时做的全是无效行，单次前向的时延不随 T 缩小而下降——tile 周期是常数。于是小 batch 下每个 token 的时延被固定 tile 成本主导，TPOT 的 P99 由最慢的那次整批路由决定。工程上的缓解不是调容量因子（本方案没有容量因子），而是 <em>batch 聚合</em>：把多个请求的 decode token 攒到接近 k 的量级再路由，用调度延迟换 tile 利用率。这与连续批处理的低延迟目标正面冲突，取舍点在于 SLO 允许的排队时间与 k 的比值。</p>\n<p>具体例子：k=128、E=64，decode batch 只有 16 个 token。每个专家从 16 个 token 里选，最多选 16 个，远不到 128；分组 GEMM 仍按 M=128 执行，有效行占比 12.5%，Tensor Core 周期里近九成是空转。此时 All-to-All 发送量仍是 E×k=8192 个槽位，而实际有效 token 只有 16 个——通信量是有效载荷的数百倍。规模上去以后，decode 侧的崩点不是显存，是这条固定成本的通信与计算被小 batch 反复摊销。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-37\">三十七 · 显存与功耗：固定 tile 的驻留成本与专家权重的静态占用</h3>\n<p>显存侧，专家选择本身不改变专家权重的驻留需求，但它改变了 <em>激活与缓冲</em> 的驻留形态。dispatch 缓冲按 E×k 常数预留，不随 T 波动，这对分页 KV 与专家权重共存的显存布局是好事——缓冲大小可预测，不会在峰值时挤占 KV 页。代价是这块缓冲在 T 小时完全闲置却仍占着显存，形成常数浪费。TMEM 侧同理：固定 M=k 让每个专家 CTA 的 TMEM 分配静态化，tcgen05 的 accumulator 驻留量可精确预算，不会出现 token-choice 下因 M 抖动导致的 TMEM 溢出回退。</p>\n<p>功耗的角度更微妙。固定 tile 意味着 SM 在无效行上照样发射 MMA，Tensor Core 的开关活动不随有效载荷下降，功耗曲线在小 batch 下保持高位而吞吐极低，能效比（token/J）塌陷。这与“算得快就省电”的直觉相反：专家选择在预填高负载时能效好，因为 tile 满载；在 decode 低负载时能效差，因为 tile 空转但电压频率不降。容量规划要把这两个阶段的功耗预算分开算，不能用一个平均功率覆盖。</p>\n<p>显存带宽上，combine 阶段的散射回写是另一处成本。被多个专家选中的 token 要按权重归一化合并，合并需要读回多个专家的部分和，读回量正比于重叠率。重叠率越高，combine 的带宽越大，而 dispatch 的带宽不变——这是一对反向指标，路由打分分布同时决定两者。工程判断：监控重叠率与零选率两个统计量，前者推高 combine 带宽与 FLOPs，后者推高残差旁路的比例，两者之和偏离 1 的程度就是这套路由在当批数据上的效率损失。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-38\">三十八 · 规模上去以后哪里先崩：一条按顺序失效的清单</h3>\n<p>把规模往上推，失效顺序是可以排出来的。第一位是 <em>decode 阶段的稀疏性塌缩</em>：T 与 k 的关系是硬约束，batch 聚合只能缓解不能消除，一旦 SLO 要求低 TPOT，这条先崩。第二位是 <em>重叠率驱动的有效 FLOPs 膨胀</em>：E 越大、k 相对 T 越小，列 top-k 的重叠越难控制，分组 GEMM 形状再完美也挡不住重复前向。第三位是 <em>All-to-All 的单向偏斜</em>：E×k 常数流量本身不随规模恶化，但 rank 间来源不均会随专家数与 rank 数增加而放大，链路利用率下降。第四位才是显存：固定缓冲与专家权重的静态占用是常数项，规模上去后占比反而下降，通常不是先崩的点。</p>\n<p>对应的工程手段各针对一层。对第一层，用预填解码分离部署把 decode 的 batch 攒大，或对 decode 走另一条路由路径（一句话指路，不展开）。对第二层，在打分矩阵上做列 top-k 的去重约束或对已选 token 降权，把重叠率压到可接受区间，代价是路由表达力下降。对第三层，按专家数做 rank 映射并在 dispatch 前重排来源。对第四层，把固定缓冲做成可回收的显存池，T 小时让给 KV 页。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先崩的环节</th><th>机理</th><th>代价形态</th></tr></thead><tbody><tr><td>batch 变小（decode）</td><td>稀疏性塌缩</td><td>T&lt;k 时列 top-k 退化为全选</td><td>TPOT 尾延迟、通信/计算固定成本</td></tr><tr><td>专家数 E 增大</td><td>重叠率上升</td><td>列 top-k 在更多列上重复选中同一 token</td><td>有效 FLOPs 高于名义值、combine 带宽</td></tr><tr><td>rank 数增大</td><td>All-to-All 偏斜</td><td>token 来源与专家映射不匹配</td><td>链路单向空转、集合通信重配置</td></tr><tr><td>显存吃紧</td><td>固定缓冲闲置</td><td>E×k 缓冲不随 T 收缩</td><td>常数显存占用挤占 KV 页</td></tr></tbody></table>\n<p>最后落在一个具体机制上：分组 GEMM 的 tile 形状固定是这套路由的全部收益来源，也是它全部代价的来源。收益是 tcgen05 流水线无气泡、All-to-All 流量可预算、TMEM 可静态分配；代价是计算量不随有效载荷收缩、通信量不随 batch 收缩、稀疏性随 T 收缩。工程判断因此不是“用不用专家选择”，而是“在哪个阶段用”——预填阶段 T 远大于 k，固定 tile 满载，这套路由的形状确定性是纯收益；decode 阶段 T 小于 k，固定成本被反复摊销，应当把路由切回按 token 选择或走 batch 聚合，把 k 与 T 的比值维持在 1 以上再谈吞吐。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-39\">三十九 · 规模放大后先崩的是解码侧稀疏性，不是显存</h3>\n<p>专家选择路由把负载均衡写进了机制：每专家沿 token 维取 top-c，得到固定 $c$ 的连续块，分组 GEMM 的 tile 形状因此完全确定，tcgen05 流水线可以按固定 M 排布而无气泡。代价被推到别处——All-to-All 发送量恒为 $E\\times c$，与真实 token 数无关。预填阶段 $T\\gg c$ 时这笔流量被摊薄；一旦 $T$ 逼近或小于 $c$，通信量不再随计算量下降，带宽先于算力成为瓶颈。设单层 dispatch 字节数为 $B_{\\text{a2a}}=E\\cdot c\\cdot d\\cdot b$（$d$ 为隐藏维、$b$ 为每元素字节），则每 token 摊到的通信量为 $B_{\\text{a2a}}/T$，$T$ 缩小时它按 $1/T$ 发散，而每 token 的有效 FLOPs 只按被选中专家数线性增长。</p>\n<p>解码侧是真正的失效点。自回归逐 token 生成时 batch 内 token 数远小于 $c$，每个专家仍要凑满 $c$ 个名额，选择退化为近似全选：名义 top-k 稀疏性消失，实际激活专家数趋近 $E$，单 token 计算量与权重读取量同步抬升，KV cache 之外又多出一份被放大的专家权重带宽压力。更麻烦的是因果性——token 能否被某专家处理取决于同批次其他 token 的打分，逐 token 的增量解码无法维持这一语义，只能按 batch 整体路由，与连续批处理中请求动态进出、序列长度不齐的调度节拍直接冲突。尾延迟由此恶化：一个短请求被迫等待同批长请求凑齐 $c$，P99 被批内最慢成员拖住。</p>\n<div class=\"formula\">$$\\text{有效稀疏度}=\\frac{1}{T}\\sum_{t}\\sum_{e}\\mathbf{I}_{t,e},\\qquad \\mathbf{I}=\\text{TopK}_{\\text{col}}(\\mathbf{G})\\in\\{0,1\\}^{T\\times E},\\ \\sum_{t}\\mathbf{I}_{t,e}=k$$</div>\n<p>上式的列和恒为 $k$ 是机制优点，行和却不受约束：部分 token 被 0 个专家选中，若无残差旁路兜底则输出缺失；被多个专家选中的 token 计算量翻倍，实际 FLOPs 高于 top-k 名义值，容量规划若按名义值估算显存与算力会系统性偏低。工程判断落在 $c$ 与 batch 的关系上：把该路由限定在预填与大批量离线推理，解码路径切回 token-choice 加容量因子，或按 $c\\le T_{\\text{batch}}$ 设定每专家容量并在专家数变化时重新调优 tile，否则固定形状反而成为流水线气泡的来源。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的资源</th><th>触发条件</th></tr></thead><tbody><tr><td>batch 缩小</td><td>稀疏性/算力</td><td>$T&lt;c$，退化为近似全选</td></tr><tr><td>专家数增多</td><td>All-to-All 带宽</td><td>$E\\cdot c$ 流量与 $T$ 脱钩</td></tr><tr><td>专家数变化</td><td>tcgen05 流水线</td><td>固定 tile 未重调优</td></tr></tbody></table>\n<h3 id=\"alg-expert-choice-routing-sec-40\">四十 · 精度问题：从路由掩码到数值漂移的三条链路</h3>\n<p>专家选择路由的精度故障很少出在 GEMM 本体，而是出在“谁被选中、以什么权重合并”这条链路上。第一条链路是打分矩阵 <b>G</b> 的数值范围：<b>G</b> 由 router 线性层加 softmax 或 sigmoid 产生，当量化把 router 权重压到 FP8 甚至 NVFP4 时，列 top-k 的边界会翻转——两个 token 对同一专家的亲和度只差一个量化步长，选择掩码就换人。诊断方法是把 router 单独拉出来跑高精度参考路径，逐列比对 top-k 集合的 Jaccard 重合度；重合度掉到阈值以下就说明 router 不该被量化，或至少该保留 FP8 权重、BF16 打分累加。第二条链路是合并权重归一化：token 被多个专家选中时按 <span class=\"formula-inline\">$\\sum_e \\mathbf{I}_{t,e}g_{t,e}$</span> 归一，若 <b>g</b> 在低精度下出现下溢，分母趋零，输出被放大成尖刺。第三条链路是残差旁路：未被任何专家选中的 token 直接透传，一旦兜底路由缺失，这批 token 的输出就与同批次其他 token 产生系统性偏差，表现为长序列生成中偶发的语义漂移而非崩溃。</p>\n<p>工程上把这三条链路做成可观测项：router 打分分布的分位数、每 token 被选中专家数 <span class=\"formula-inline\">$|\\{e:\\mathbf{I}_{t,e}=1\\}|$</span> 的直方图、归一化分母的最小值。三者任一越界即触发回滚到 BF16 router 路径，代价是 router 那几层的小算子吞吐下降，但相对整网 GEMM 占比极小，属于可接受的保险成本。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-41\">四十一 · OOM：固定 c 带来的显存确定性与其反面</h3>\n<p>专家选择路由的显存账本比容量因子路由更“硬”：All-to-All 发送量严格为 <b>E×c</b>，分组 GEMM 的激活缓冲按固定 tile 分配，因此预填阶段的峰值显存几乎可以离线算出来。这既是优点也是失败模式的来源——一旦 <b>c</b> 被调大或专家数 <b>E</b> 被扩，缓冲尺寸线性上涨，而分页 KV 与专家权重共享同一块 HBM 时，OOM 往往不是渐进出现，而是在某个 batch 跨过阈值时突然触发。诊断要点是区分“激活 OOM”与“KV OOM”：前者表现为 prefill 阶段瞬时峰值，后者表现为 decode 阶段随序列增长缓慢爬升。前者可通过缩小 <b>c</b> 或切分 prefill 块缓解，后者只能靠 KV 分页回收或降低并发。</p>\n<p>另一个隐蔽的 OOM 源是被多专家选中的 token：名义 FLOPs 是 top-k 的 k 倍，但实际被选中次数分布有长尾，某些 token 被 3 个以上专家选中时，combine 阶段的中间缓冲要按最大重数分配，而非按平均值。监控项应包含每 token 选中重数的 P99，用它而不是均值去定缓冲尺寸，否则长尾批次会周期性打爆显存。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-42\">四十二 · 批抖动与路由不均：固定 tile 的两种反面</h3>\n<p>固定 tile 是这套路由的核心收益，也是抖动之源。分组 GEMM 以 M=c 执行，tcgen05 流水线在 tile 形状恒定时无气泡；但当实际到达某专家的 token 数不足 c（例如 batch 内 token 总数 T 接近或小于 c），该专家的 tile 出现空洞，流水线被迫等待，吞吐按空洞比例下降。更糟的是路由不均的另一种形态：由于是专家沿 token 维取 top-c，热门专家会把同一批高亲和度 token 反复吸走，冷门专家拿到的 token 亲和度低，合并权重小，输出贡献被稀释——这不会报错，但会让专家利用率的名义 100% 变成有效利用率远低于 100%。</p>\n<p>诊断批抖动看两个量：每专家实际填充率 <span class=\"formula-inline\">$\\rho_e = |\\mathcal{T}_e|/c$</span> 的方差，以及相邻 micro-batch 之间同一专家 token 集合的重合度。前者高说明 tile 空洞在专家间轮转，后者低说明路由在时间上不稳定，调度器难以做专家亲和性缓存。工程判断是：当 T 与 c 同量级时，这套路由的稀疏性已经退化，应切换到容量因子路由或直接稠密执行，而不是硬撑固定 tile。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-43\">四十三 · 尾延迟尖刺：decode 阶段的退化与兜底缺失</h3>\n<p>自回归解码是这套路由最脆弱的场景。decode 时 batch 内 token 数远小于 c，每个专家沿 token 维取 top-c 实际退化为近似全选，稀疏性消失，All-to-All 仍按 E×c 发送但其中大量是重复或低亲和度 token，通信量不降反升。尾延迟尖刺通常出现在两个时刻：一是长序列 decode 中某步 batch 突然扩容，路由重算使该步的专家集合整体换血，All-to-All 与 GEMM 都要重新热身；二是兜底路由缺失时，未被选中的 token 走残差旁路，其后续层的注意力模式与同批其他 token 分叉，导致该请求的后续步出现计算路径不一致，表现为单请求 P99 延迟抬升而均值不变。</p>\n<p>监控上把 decode 阶段的“有效稀疏度”作为一级指标：每 token 平均被选中专家数除以 E，若该值在 decode 中持续高于预填阶段的数倍，说明已退化。回滚策略是 decode 阶段禁用专家选择路由、退回 token-choice 加容量因子，或对小 batch 直接稠密执行；预填阶段保留专家选择以吃满固定 tile 收益。这种按阶段切换的混合部署是这套路由在线上最稳的形态。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-44\">四十四 · 监控面与回滚开关的设计</h3>\n<p>把上述失败模式收敛成一组可自动判定的信号，挂在请求级与批次级两个粒度上。请求级看输出一致性（与高精度参考路径的偏差）、每 token 选中重数、是否走残差旁路；批次级看每专家填充率方差、All-to-All 实际字节数与理论 E×c 的比值、分组 GEMM 的 tile 空洞率、router 打分 top-k 边界翻转率。每个信号配一个硬阈值和一个软阈值，软阈值触发降级（router 升精度、c 下调），硬阈值触发回滚（整段切回容量因子路由）。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>观测粒度</th><th>典型成因</th><th>动作</th></tr></thead><tbody><tr><td>top-k 集合翻转率</td><td>批次</td><td>router 量化过深</td><td>router 回 BF16</td></tr><tr><td>归一化分母最小值</td><td>token</td><td>低精度下溢</td><td>合并权重升精度</td></tr><tr><td>选中重数 P99</td><td>批次</td><td>长尾多选</td><td>扩 combine 缓冲</td></tr><tr><td>填充率方差</td><td>批次</td><td>T 接近 c</td><td>切容量因子路由</td></tr><tr><td>残差旁路比例</td><td>请求</td><td>兜底缺失</td><td>启用兜底路由</td></tr><tr><td>decode 有效稀疏度</td><td>阶段</td><td>batch 远小于 c</td><td>decode 禁用本路由</td></tr></tbody></table>\n<p>回滚必须是配置级而非代码级：把路由策略、c、router 精度、兜底开关做成运行时可切的参数，回滚延迟控制在秒级，避免故障期间重启服务。回滚后要保留原路由的掩码采样日志，用于事后定位是精度、负载还是 batch 形态触发的。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-45\">四十五 · 工程判断：什么情况下不该用这套路由</h3>\n<p>失败模式的集合本身给出了适用边界的反面判据。当 decode 占主导、batch 内 token 数长期低于 c 时，稀疏性退化使固定 tile 的收益归零而通信开销照付，此时应直接放弃专家选择路由；当专家数 <b>E</b> 频繁变动或 c 需要在线调优时，固定 tile 需重新调优否则 tcgen05 流水线出气泡，运维成本高于收益；当兜底路由无法低成本实现时，残差旁路带来的输出缺失是不可接受的正确性风险。反过来，预填阶段 token 数远大于 c、专家集合稳定、能接受按 batch 整体路由破坏逐 token 因果性的场景，才是这套机制真正兑现“负载由算法保证、无丢弃、tile 恒定”的地方。诊断体系的价值不在于事后救火，而在于用填充率方差与有效稀疏度这两个量，提前判断当前流量形态是否已经滑出这个窗口。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-46\">四十六 · 专家反向路由的失效边界与上线诊断</h3>\n<p>反向路由把“每专家恰好 c 个 token”从统计期望变成机制约束，代价是把不均衡从专家维度搬到了 token 维度。诊断的第一原则是：不要只看专家负载方差，要看 token 被选次数的分布。定义每个 token 的命中数 $n_t=\\sum_e \\mathbf{I}_{t,e}$，则实际 FLOPs 与名义 top-k 的比值可写成 <div class=\"formula\">$$\\rho=\\frac{\\sum_t n_t}{T\\cdot k}=\\frac{E\\cdot c}{T\\cdot k}$$</div> 当 $T\\gg c$ 时 $\\rho\\to 1$，预填阶段分组 GEMM 的 tile 形状稳定，tcgen05 流水线无气泡；当 $T$ 逼近或小于 $c$ 时，$\\rho$ 迅速抬升，因为 $E\\cdot c$ 的下界由专家数决定而 $T\\cdot k$ 随 batch 缩小。这就是解码阶段的退化：batch 内 token 数远小于 c，每个专家沿 token 维取 top-c 实际等于全选，稀疏性消失，All-to-All 发送量仍是 $E\\times c$ 却只服务少量 token，通信与 GEMM 的固定开销被摊到极少数请求上，单 token 延迟抬升而吞吐不增。监控上应把 $\\rho$ 与 $T/c$ 作为一对孪生指标同时采集，前者反映算力浪费，后者反映稀疏性余量。</p>\n<p>第二类失效是 token 侧的空洞与重复。反向路由允许某 token 被 0 个专家选中，若 combine 阶段没有残差旁路兜底，该 token 的输出直接缺失，表现为生成文本出现断句、重复或语义漂移，且这种错误不体现在专家负载指标上——负载依然完美等于 c。工程上必须把“未命中 token 比例”做成硬指标：$\\phi_0=\\frac{1}{T}\\sum_t \\mathbb{1}[n_t=0]$，以及重复度 $\\phi_{\\ge2}$。前者走高说明亲和度矩阵 $S$ 的列 top-c 与行分布错位，需要检查打分函数的温度与归一化；后者走高说明计算量翻倍，$\\rho$ 上升。一个具体例子：某请求 batch 内 $T$ 略大于 $c$，专家列 top-c 几乎覆盖全部 token，$\\phi_{\\ge2}$ 显著上升，分组 GEMM 的固定 tile 仍按 c 执行，但 combine 时每 token 需按其命中数加权平均，归约分支从单路变成多路，尾延迟尖刺往往就出现在这里——不是 GEMM 慢，而是 combine 的散射与归一化在 token 命中数不均时出现分支发散。</p>\n<p>第三类是形状与配置漂移。固定 tile 形状依赖 c 与专家数 E，一旦扩缩容改变 E 或调整 c，tcgen05 的分组 GEMM 流水线需要重新调优，否则出现气泡；这类问题在压测中不易复现，因为气泡只在特定 E、c 与 SM 占用组合下暴露。诊断手段是把每次路由的 $(T,E,c)$ 与实测 GEMM 有效算力比一起打点，形成一张小表对照：</p>\n<table class=\"mini\"><thead><tr><th>观测项</th><th>异常指向</th><th>系统代价</th></tr></thead><tbody><tr><td>$\\rho$ 持续大于 1</td><td>token 重复命中，稀疏性损失</td><td>FLOPs 与功耗上升，吞吐不增</td></tr><tr><td>$\\phi_0$ 非零</td><td>缺兜底旁路，输出缺失</td><td>正确性事故，尾延迟不可预测</td></tr><tr><td>$T/c$ 接近 1</td><td>解码退化近似全选</td><td>All-to-All 固定流量摊薄，单 token 延迟抬升</td></tr><tr><td>GEMM 有效算力比下降</td><td>E 或 c 变更后 tile 未重调</td><td>tcgen05 流水线气泡，显存带宽空转</td></tr></tbody></table>\n<p>回滚策略必须按失效类型分层，而不是整体切回 token-choice。对 $\\phi_0$ 类正确性问题，回滚点是打开残差旁路并把未命中 token 强制送入打分最高的单专家，代价是破坏“每专家恰好 c”的严格性，需同步放宽 c 的硬约束；对 $\\rho$ 类算力浪费，回滚点是在 $T/c$ 低于阈值时切回 token-choice 加容量因子，用丢弃兜底换取解码阶段的稀疏性；对形状漂移，回滚点是锁定上一版 $(E,c)$ 配置并冻结扩缩容，直到 tile 重调完成。判断阈值不能拍脑袋，应以 $\\rho$ 与尾延迟分位数联动：当 $\\rho$ 抬升但 P99 未动，说明浪费尚可接受；当 $\\rho$ 抬升且 P99 出现尖刺，说明 combine 分支发散已成瓶颈，此时回滚收益最大。最后一条工程判断：反向路由的监控必须把“专家负载完美”当作必要非充分条件，负载方差为零恰恰会掩盖 token 侧的全部问题。</p>\n<h3 id=\"alg-expert-choice-routing-sec-47\">四十七 · 对照轴：谁在决定\"哪个 token 进哪个专家\"</h3>\n<p>把专家选择路由（Expert Choice，下称 EC）放回同族谱系里，唯一真正决定工程行为的对照轴是<strong>选择方向</strong>：token-choice（下称 TC）由 token 发起、对每个 token 取 top-k 专家；EC 由专家发起、对每个专家沿 token 维取 top-c。这一条方向差异会沿着整条推理栈向下传导——路由矩阵的转置、All-to-All 的发送量、分组 GEMM 的 M 维、combine 的归一化分母、以及能否在 decode 阶段成立。选型时不要先问\"哪个精度高\"，先问\"我的负载由谁保证\"。TC 的负载由数据分布决定，是统计量；EC 的负载由算法强制为每专家恰好 c，是常量。凡是下游依赖\"形状可预测\"的环节（tcgen05 分组 GEMM 的 tile、TMEM 分配、All-to-All 缓冲区预留），常量形状的价值远大于统计均值。</p>\n<p>第二根轴是<strong>稀疏性是否可控</strong>。TC 下每个 token 恰好被 k 个专家处理，FLOPs 名义值等于 T×k×专家单次计算量，实际因丢弃略低；EC 下每个专家恰好处理 c 个 token，总计算量为 E×c，但单个 token 被 0 个或多个专家命中的次数是随机变量，实际 FLOPs 围绕 E×c 波动，且部分 token 走残差旁路、部分 token 被重复计算。第三根轴是<strong>因果性</strong>：EC 的选择依赖同批次全部 token，逐 token 自回归生成与之不兼容；TC 的 top-k 只依赖当前 token，天然流式。这三根轴构成决策表的骨架，其余细节都是它们的推论。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-48\">四十八 · 决策表：按推理阶段与负载形态落位</h3>\n<p>下表把可用事实中的适用条件压缩成可执行的判据。判据不是\"哪个更好\"，而是\"在给定阶段与批形态下，哪个的代价落在可接受的一侧\"。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>选 EC（专家选择）</th><th>选 TC + 容量因子</th></tr></thead><tbody>\n<tr><td>推理阶段</td><td>预填为主，T 远大于 c</td><td>解码为主，逐 token 流式</td></tr>\n<tr><td>负载保证</td><td>算法强制，每专家 = c</td><td>统计 + 事后截断，靠丢弃兜底</td></tr>\n<tr><td>GEMM 形状</td><td>固定 tile，M = c</td><td>tile 随批次抖动，需 padding</td></tr>\n<tr><td>All-to-All 量</td><td>严格 E×c，可预留缓冲</td><td>随路由分布浮动</td></tr>\n<tr><td>稀疏性</td><td>token 侧不可控（0 或多命中）</td><td>token 侧恒为 k</td></tr>\n<tr><td>因果性</td><td>破坏，需整批路由</td><td>保持，可逐 token</td></tr>\n<tr><td>兜底需求</td><td>必须有残差旁路</td><td>必须有容量因子与丢弃策略</td></tr>\n</tbody></table>\n<p>读表的关键在于：<strong>预填与解码是两个不同的路由问题</strong>。预填阶段一个 chunk 动辄上千 token，T≫c 成立，EC 的固定 tile 让 tcgen05 流水线无气泡，收益直接兑现；解码阶段 batch 内 token 数远小于 c，专家沿 token 维取 top-c 会退化为近似全选，稀疏性消失，EC 的机制优势归零而代价（整批路由、因果性破坏）仍在。因此工程判断是：<strong>预填走 EC、解码走 TC</strong>，而不是全局二选一。这与分块预填与解码 piggyback、预填解码分离部署的切分逻辑同构——阶段不同，路由策略就该不同。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-49\">四十九 · 公式对照：两条路径的代价函数</h3>\n<p>EC 的完整前向可写为：</p>\n<div class=\"formula\">$$\\mathbf{I}=\\text{TopK}_{\\text{col}}\\left(\\mathbf{G}\\right)\\in\\{0,1\\}^{T\\times E},\\quad \\sum_{t}\\mathbf{I}_{t,e}=k\\ \\ \\forall e,\\quad \\mathbf{y}_t=\\frac{\\sum_e \\mathbf{I}_{t,e}\\,g_{t,e}\\,\\text{Expert}_e(\\mathbf{x}_t)}{\\sum_e \\mathbf{I}_{t,e}g_{t,e}}$$</div>\n<p>注意约束写在<strong>列和</strong>上：对每个专家 e，被选中的 token 数恒为 k（即上文容量 c）。这与 TC 的约束写在行和上（每 token 恰好 k 个专家）正好互为转置。转置的代价立刻显形：行和不再受约束，$\\sum_e \\mathbf{I}_{t,e}$ 对单个 token 可以是 0、1、2……于是分母 $\\sum_e \\mathbf{I}_{t,e}g_{t,e}$ 在 0 命中时为零，必须走残差旁路；在多命中时归一化正确但计算量翻倍。EC 的实际 FLOPs 期望可写成 $\\mathbb{E}[\\text{FLOPs}] = E\\cdot c \\cdot (1 + \\text{重复命中率})$，重复命中率由打分矩阵的集中度决定，无法从事先给定的 c 推出。</p>\n<p>TC 侧的代价函数则是另一副面孔：名义 FLOPs 恒为 T×k，但分组 GEMM 的 M 维等于各专家实际收到 token 数的最大值乘以容量因子，padding 与丢弃同时存在，有效吞吐 = 名义吞吐 × 专家利用率。两条路径的取舍因此可以写成一句工程不等式：当 EC 的重复命中率带来的额外 FLOPs 小于 TC 因 tile 抖动与丢弃损失的利用率时，EC 在预填阶段占优；反之 TC 占优。这个不等式没有闭式解，只能靠实测的命中分布来判。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-50\">五十 · 机制落地：固定 tile 与残差旁路的耦合代价</h3>\n<p>EC 的机制步骤是：算 T×E 亲和度矩阵 S，每专家沿 token 维取 top-c 得到 E×c 掩码，按专家维重排 token 形成 E 个大小恰为 c 的连续块，分组 GEMM 以固定 tile 执行，结果按 token 索引散射回序列。固定 tile 的直接收益是 tcgen05 流水线无气泡、TMEM 分配可静态规划、All-to-All 发送量严格为 E×c 因而缓冲区可预留——这三项合起来把预填阶段的分组 GEMM 从\"形状抖动 + padding\"变成\"常量形状\"，是 EC 在 Blackwell 上最实的收益。</p>\n<p>但固定 tile 与残差旁路耦合后产生一笔隐性代价：未被任何专家选中的 token 不进入任何 GEMM tile，其输出必须由旁路补齐，这意味着散射回序列时存在\"空洞\"，combine 核需要按 token 索引判断该 token 是否有专家输出。多命中的 token 则在同一 tile 内被多个专家重复计算，其 combine 权重需归一化，且这部分 FLOPs 不体现在 E×c 的名义值里。工程上必须把这两类 token 的比例作为监控指标——它们是 EC 部署后最先劣化的量。另一个耦合点是专家数变化：固定 tile 形状在 E 变化时需重新调优，否则 tcgen05 流水线出现气泡，这条失败模式在扩缩容或专家并行重切分时必然触发。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-51\">五十一 · 适用条件与不可用条件</h3>\n<p>EC 可用的充分条件有三条，缺一不可：其一，阶段为预填或 T 远大于 c 的批量场景，保证稀疏性不退化为全选；其二，系统能接受整批路由，即不要求逐 token 流式生成；其三，下游有残差旁路与多命中归一化的实现，而非假设每 token 恰好一个专家。三条同时成立时，EC 把负载均衡从\"统计保证 + 丢弃兜底\"升级为\"机制保证\"，专家利用率接近 100%，容量因子与令牌丢弃这两个调参项整体消失。</p>\n<p>不可用条件同样清晰：解码阶段 batch 内 token 数远小于 c 时，专家沿 token 维取 top-c 退化为近似全选，稀疏性消失而整批路由的代价仍在，此时应切回 TC；缺乏兜底路由时，未被选中的 token 输出缺失，这是正确性问题而非性能问题；专家数频繁变化且未重调 tile 时，tcgen05 流水线气泡会吃掉固定形状的全部收益。规模上限受 c 与 batch 大小的关系约束——c 越大，EC 越只在长预填 chunk 上成立；c 越小，每专家负载越轻但重复命中率上升。这个上限没有解析式，只能由实测的命中分布与 tile 调优结果共同划定。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-52\">五十二 · 与容量因子路由的边界划法</h3>\n<p>把两条路径的失败模式并排放，边界就出来了。TC 的失败模式是负载不均导致的溢出与丢弃，容量因子调大则 padding 浪费、调小则丢 token，本质是在\"算力浪费\"与\"信息损失\"之间做静态权衡，且权衡点随数据分布漂移。EC 的失败模式是 token 侧稀疏性不可控——0 命中导致输出缺失、多命中导致 FLOPs 超名义值，本质是把不确定性从专家维转移到了 token 维。选型的实质是<strong>选择把不确定性放在哪一维</strong>：如果你的下游对专家维形状敏感（分组 GEMM、All-to-All 缓冲、TMEM 规划），把不确定性推到 token 维、用残差旁路兜住，是划算的；如果你的下游对 token 级因果性与逐 token 延迟敏感（decode、流式），把不确定性留在专家维、用容量因子截断，是唯一可行解。</p>\n<p>因此同族算法的选型不该是单点决策，而应写成按阶段的策略表：预填 chunk 走 EC 拿固定 tile，解码走 TC 保因果，两段之间用预填解码分离部署的切分点衔接，KV 与专家权重的共存按分页 KV 的方案处理。真正需要盯住的工程量只有两个：EC 侧的 0 命中率与多命中率，TC 侧的专家利用率与丢弃率。前者决定残差旁路的带宽开销与 combine 核的分支成本，后者决定容量因子的调参频率。这两个量一旦在监控上稳定，路由策略就不必再动；一旦漂移，说明数据分布已越过适用边界，应重新落位而非继续调参。</p>\n\n<h3 id=\"alg-expert-choice-routing-sec-53\">五十三 · 专家选择路由的边界：与容量因子路由、分组 GEMM 调度族的取舍</h3>\n\n<p>把专家选择路由放进同族算法的坐标系里，真正的分水岭不是“谁更均衡”，而是<strong>均衡由谁保证</strong>。token-choice 路由的负载是数据分布的统计结果，容量因子只是事后截断，分组 GEMM 的 tile 形状随批次抖动，tcgen05 流水线要么按最坏情况预留、要么频繁换 tile 配置。专家选择路由把选择方向反过来：每个专家沿 token 维取 top-c，$\\mathcal{T}_e=\\text{top-}c(\\{S_{t,e}\\}_{t=1}^{T})$，每专家负载恒等于 c，dispatch 矩阵转置后 All-to-All 发送量严格为 $E\\times c$，GEMM 以固定 M=c 执行。代价立刻显形：token 可能被 0 个专家选中而走残差旁路，也可能被多个专家选中使实际 FLOPs 高于名义稀疏度。因此选型的第一问是——你的瓶颈是<strong>形状确定性</strong>还是<strong>token 覆盖率</strong>。</p>\n\n<p>决策表按三个可观测条件切分，而不是按算法名气：</p>\n\n<table class=\"mini\">\n<thead><tr><th>条件</th><th>专家选择路由</th><th>容量因子 token-choice</th><th>无丢弃的软容量/重排方案</th></tr></thead>\n<tbody>\n<tr><td>每步 token 数 T 与 c 的关系</td><td>T≫c 才稀疏；T≲c 退化为近似全选</td><td>任意 T，但丢弃率随 T/c 上升</td><td>任意 T，靠重排与溢出缓冲兜底</td></tr>\n<tr><td>GEMM tile 形状</td><td>固定，流水线无气泡</td><td>抖动，需按最坏情况预留</td><td>近似固定，缓冲带来额外拷贝</td></tr>\n<tr><td>因果性</td><td>破坏：需按 batch 整体路由</td><td>保持：逐 token 可路由</td><td>保持，但引入跨 token 依赖</td></tr>\n<tr><td>输出完整性</td><td>需兜底路由补 0 选中 token</td><td>丢弃即信息损失</td><td>无损失，显存与带宽代价上升</td></tr>\n<tr><td>All-to-All 流量</td><td>确定 $E\\times c$</td><td>随实际负载波动</td><td>确定但含重分发开销</td></tr>\n</tbody>\n</table>\n\n<p>失效条件集中在两处。其一是<strong>解码阶段的稀疏性塌缩</strong>：自回归 decode 时 batch 内 token 数远小于 c，每个专家沿 token 维取 top-c 实际接近全选，专家选择退化为稠密计算，All-to-All 仍按 $E\\times c$ 发送，通信量与计算量双双失去稀疏收益——此时它严格劣于容量因子路由。其二是<strong>覆盖率缺口</strong>：未被任何专家选中的 token 若没有兜底路由，输出直接缺失；被多个专家选中的 token 需按选中数归一化，$\\mathbf{y}_t={\\sum_e \\mathbf{I}_{t,e}g_{t,e}\\text{Expert}_e(\\mathbf{x}_t)}/{\\sum_e\\mathbf{I}_{t,e}g_{t,e}}$，分母随选中数变化，实际 FLOPs 与 combine 带宽都高于 top-k 名义值。系统代价因此可写成一条判断式：设平均选中数为 $\\bar{k}$，则有效计算量约为名义值的 $\\bar{k}/k$ 倍，而收益只在 $T\\gg c$ 时兑现。</p>\n\n<p>工程判断落在部署形态上：预填阶段 T 远大于 c，专家选择路由的固定 tile 让 tcgen05 流水线无气泡，配合分离式预填/解码把 decode 交给 token-choice 或软容量方案，是这套机制唯一自洽的用法；专家数变化时必须重新调优 tile 尺寸，否则固定形状反而制造气泡。若业务以长上下文预填为主、SLO 压在首 token 延迟上，选它；若以流式 decode 为主、batch 小且抖动大，选容量因子加溢出缓冲，并接受丢弃率作为显式指标而非隐藏故障。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 专家并行与All-to-All通信</td></tr><tr><td>解决什么</td><td>token 选择专家的 top-k 路由天然造成负载不均，容量因子只能靠丢弃来兜底；需要一种从机制上保证每专家负载严格…</td></tr><tr><td>一句话机制</td><td>反转路由方向：每个专家按打分挑选固定数量 k 的 token，使每专家负载恒等于 k，天然无丢弃、无溢出，代价是 to…</td></tr><tr><td>代价与失效</td><td>因果性被破坏：token 能否被专家处理取决于同批次其他 token，自回归 decode 时需按 batch 整体路由，与逐 token…</td></tr><tr><td>后继</td><td>NVFP4 权重与激活量化</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-expert-choice-routing · 共 8 个片段</p>\n";break;}}})();
